  select 1 from public.syllabus_editions
  where contest_name='Polícia Civil do Distrito Federal' and role_name='Delegado de Polícia' and contest_year=2026
);

with edition as (
  select id from public.syllabus_editions
  where contest_name='Polícia Civil do Distrito Federal' and role_name='Delegado de Polícia' and contest_year=2026
)
insert into public.syllabus_topics (edition_id,block_name,discipline,topic_order,topic_text,content_status)
select edition.id,'Prova objetiva (P1)',d.discipline,1,d.topic_text,'current'
from edition cross join (values
('Direito Administrativo','Legislação complementar de direito administrativo (Lei nº 14.133/2021, Lei nº 12.846/2013, Lei Complementar Distrital nº 840/2011), princípios da administração pública, órgãos públicos, administração indireta, entidades paraestatais, atos administrativos, poderes da administração, bens públicos, licitações, controle da administração e regime jurídico dos servidores públicos, LINDB e Decreto nº 9.830/2019.'),
('Direito Constitucional','Classificações das constituições, poder constituinte, interpretação constitucional, controle de constitucionalidade, direitos e deveres fundamentais, organização do Estado, administração pública, defesa do Estado e das instituições democráticas e segurança pública.'),
('Legislação de Segurança Pública','Sistema Único de Segurança Pública (Lei nº 13.675/2018) e Lei Orgânica Nacional das Polícias Civis (Lei nº 14.735/2023).'),
('Direito Civil','Pessoas naturais, direitos da personalidade, domicílio, negócios jurídicos, atos ilícitos, responsabilidade civil, prescrição, decadência e posse.'),
('Direito Empresarial','Empresário, sociedades empresárias, recuperação judicial e falência (Lei nº 11.101/2005) e liberdade econômica (Lei nº 13.874/2019).'),
('Direito Penal','Parte geral e parte especial do Código Penal e legislação penal especial correlata (Lei nº 10.826/2003, Lei nº 11.340/2006, Lei nº 11.343/2006, Lei nº 13.869/2019, Lei nº 9.455/1997).'),
('Direito Tributário','Tributos em espécie, incluindo o IBS instituído pela Reforma Tributária do Consumo, e crédito tributário conforme o Código Tributário Nacional (CTN).'),
('Medicina Legal','Lesões por descarga atmosférica, documentos médico-legais, sexologia forense, infanticídio e aborto.'),
('Direito Processual Penal','Princípios gerais da prova no processo penal, procedimento probatório, valoração da prova, ilicitude probatória e prisão.'),
('Legislação Especial (Violência Doméstica e Familiar)','Lei Maria da Penha (Lei nº 11.340/2006) e Lei Henry Borel (Lei nº 14.344/2022).'),
('Legislação Especial (Organizações Criminosas, Lavagem de Dinheiro e Drogas)','Lei nº 12.850/2013 (organizações criminosas), Lei nº 9.613/1998 (lavagem de dinheiro) e Lei nº 11.343/2006 (drogas).'),
('Direito Ambiental','Lei nº 9.605/1998, Decreto nº 6.514/2008, biossegurança, SISNAMA e SNUC.'),
('Administração Regional e Políticas Distritais','Região Integrada de Desenvolvimento do Distrito Federal e Entorno (RIDE) e II Plano Distrital de Política para Mulheres (II PDPM).'),
('Primeiros Socorros','Noções de primeiros socorros e suporte básico de vida.')
) d(discipline,topic_text)
on conflict (edition_id,discipline,topic_order) do update set topic_text=excluded.topic_text;

with imported(exam_year,item_number,subject,question_text,raw_extraction,official_answer,source_page,content_status,legal_review_required,context_review_required,review_note,legal_basis_text) as (values
(2026,1,$q$Direito Administrativo$q$,$q$O Portal Nacional de Contratações Públicas (PNCP) é um sítio eletrônico oficial destinado à divulgação centralizada e obrigatória dos atos exigidos pela Lei n.º 14.133/2021, bem como destinado à realização facultativa das contratações pelos órgãos e entidades dos Poderes Executivo, Legislativo e Judiciário, no âmbito exclusivo da União.$q$,$q$O Portal Nacional de Contratações Públicas (PNCP) é um sítio eletrônico oficial destinado à divulgação centralizada e obrigatória dos atos exigidos pela Lei n.º 14.133/2021, bem como destinado à realização facultativa das contratações pelos órgãos e entidades dos Poderes Executivo, Legislativo e Judiciário, no âmbito exclusivo da União.$q$,'E',1,'under_review',true,false,$q$O PNCP não se restringe ao âmbito da União. De acordo com o art. 174 da Lei n.º 14.133/2021, o PNCP é destinado à realização facultativa das contratações pelos órgãos e entidades dos Poderes Executivo, Legislativo e Judiciário de todos os entes federativos.$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,2,$q$Direito Administrativo$q$,$q$A Lei n.º 12.846/2013, conhecida como Lei Anticorrupção, aplica-se aos atos lesivos praticados por pessoas jurídicas contra a administração pública estrangeira.$q$,$q$A Lei n.º 12.846/2013, conhecida como Lei Anticorrupção, aplica-se aos atos lesivos praticados por pessoas jurídicas contra a administração pública estrangeira.$q$,'X',1,'annulled',true,false,$q$O art. 1.º da Lei n.º 12.846/2013 dispõe expressamente que a referida lei dispõe sobre a responsabilização objetiva administrativa e civil de pessoas jurídicas pela prática de atos contra administração pública, nacional ou estrangeira.$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,3,$q$Direito Administrativo$q$,$q$A conduta de policial civil do Distrito Federal que divulga, sem autorização e em prejuízo do serviço, informação de caráter restrito de que tenha ciência em razão da função policial ou propicia a sua divulgação é considerada infração disciplinar punível com demissão.$q$,$q$A conduta de policial civil do Distrito Federal que divulga, sem autorização e em prejuízo do serviço, informação de caráter restrito de que tenha ciência em razão da função policial ou propicia a sua divulgação é considerada infração disciplinar punível com demissão.$q$,'E',1,'under_review',true,false,$q$O art. 12 da Lei n.º 15.047/2024 prevê pena de suspensão de 31 a 45 dias, e não de demissão, para o policial civil do Distrito Federal que divulgar, sem estar autorizado, informação de caráter restrito de que tenha ciência em razão da função policial ou propiciar a sua divulgação, em prejuízo do serviço.$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,4,$q$Direito Administrativo$q$,$q$De acordo com a Lei Complementar do Distrito Federal n.º 840/2011, a responsabilidade administrativa do servidor não é afastada no caso de absolvição penal com decisão transitada em julgado que reconheça que o fato não constitui infração penal.$q$,$q$De acordo com a Lei Complementar do Distrito Federal n.º 840/2011, a responsabilidade administrativa do servidor não é afastada no caso de absolvição penal com decisão transitada em julgado que reconheça que o fato não constitui infração penal.$q$,'C',1,'under_review',true,false,$q$De acordo com o art. 181 da Lei Complementar n.º 840/2011 do Distrito Federal, a responsabilidade administrativa do servidor somente será afastada no caso de absolvição penal, com decisão transitada em julgado que negue a existência do fato ou a sua autoria, logo a responsabilidade não será afastada ainda que se reconheça que o fato não constitui infração penal.$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,5,$q$Direito Administrativo$q$,$q$Não é possível a dupla responsabilização pelo crime eleitoral conhecido como “caixa dois” e por ato de improbidade administrativa.$q$,$q$Não é possível a dupla responsabilização pelo crime eleitoral conhecido como “caixa dois” e por ato de improbidade administrativa.$q$,'E',1,'under_review',true,false,$q$No julgamento do Tema de Repercussão Geral 1260, o STF estabeleceu que é possível a dupla responsabilização por crime eleitoral caixa dois (Código Eleitoral, art. 350) e ato de improbidade administrativa (Lei n.º 8.429/1992), pois a independência de instâncias exige tratamentos sancionatórios diferenciados entre os atos ilícitos em geral (civis, penais e político-administrativos) e os atos de improbidade administrativa.$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,6,$q$Direito Administrativo$q$,$q$A vedação ao nepotismo decorre diretamente dos princípios mencionados no art. 37, caput, da Constituição Federal de 1988, não se exigindo edição de lei formal para coibir tal prática.$q$,$q$A vedação ao nepotismo decorre diretamente dos princípios mencionados no art. 37, caput, da Constituição Federal de 1988, não se exigindo edição de lei formal para coibir tal prática.$q$,'C',1,'under_review',true,false,$q$Conforme consta na tese de repercussão geral fixada pelo STF, no julgamento do Tema de Repercussão Geral 66, a “vedação ao nepotismo não exige a edição de lei formal para coibir a prática, dado que essa proibição decorre diretamente dos princípios contidos no art. 37, caput, da Constituição Federal”.$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,7,$q$Direito Administrativo$q$,$q$Os órgãos públicos independentes, a exemplo da câmara de vereadores e da assembleia legislativa, possuem personalidade jurídica e, por isso, podem demandar em juízo para defender os seus direitos institucionais.$q$,$q$Os órgãos públicos independentes, a exemplo da câmara de vereadores e da assembleia legislativa, possuem personalidade jurídica e, por isso, podem demandar em juízo para defender os seus direitos institucionais.$q$,'E',1,'under_review',true,false,$q$Órgãos públicos independentes como Câmara de Vereadores, Assembleia Legislativa, Câmara dos Deputados, Presidência da República e tribunais não possuem personalidade jurídica, pois o art. 41 do Código Civil não os inclui no rol de pessoas jurídicas de direito público, sendo eles, à luz da teoria do órgão (Otto Gierke, difundida no Brasil por Hely Lopes Meirelles), meros centros de competência despersonalizados, integrantes da pessoa jurídica maior a que pertencem (o ente federativo), sem vontade própria; entretanto, para preservar o princípio da separação dos Poderes (art. 2º da CF) e garantir que a autonomia institucional de cada Poder possa ser defendida em juízo, inclusive contra invasões de outro Poder, a jurisprudência do STF e do STJ construiu a figura da personalidade judiciária, capacidade processual excepcional e limitada à defesa de direitos e prerrogativas institucionais, entendimento consolidado na Súmula 525 do STJ ("A Câmara de Vereadores não possui personalidade jurídica, apenas personalidade judiciária, para demandar em juízo unicamente para defender a sua capacidade processual em ações que visem à defesa de seus direitos institucionais"), aplicado por extensão aos demais órgãos independentes e reforçado, no plano processual, pela interpretação analógica do art. 75 do CPC quanto à representação em juízo desses entes.$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,8,$q$Direito Administrativo$q$,$q$É possível a criação, por lei federal, de empresa pública com personalidade jurídica de direito privado e patrimônio próprio e com capital social pertencente exclusivamente à União.$q$,$q$É possível a criação, por lei federal, de empresa pública com personalidade jurídica de direito privado e patrimônio próprio e com capital social pertencente exclusivamente à União.$q$,'E',1,'under_review',true,false,$q$O art. 3.º da Lei n.º 13.303/2016 define empresa pública nos seguintes termos: “empresa pública é a entidade dotada de personalidade jurídica de direito privado, com criação autorizada por lei e com patrimônio próprio, cujo capital social é integralmente detido pela União, pelos estados, pelo Distrito Federal ou pelos municípios”.$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. ATENÇÃO: a resposta do gabarito preliminar com justificativas (item 8) foi 'C', divergente da resposta do gabarito oficial definitivo ('E') — provável alteração por recurso; justificativa abaixo reflete o raciocínio do gabarito PRELIMINAR e pode não corresponder à fundamentação da resposta definitiva. Necessária revisão jurídica específica antes de content_status=active. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,9,$q$Direito Administrativo$q$,$q$A distinção entre decreto e resolução decorre exclusivamente da finalidade normativa de cada ato.$q$,$q$A distinção entre decreto e resolução decorre exclusivamente da finalidade normativa de cada ato.$q$,'E',1,'under_review',true,false,$q$A distinção entre decreto e resolução não é finalística, mas sim subjetiva/formal, baseada na autoridade competente para editar o ato: o decreto é privativo do Chefe do Poder Executivo (Presidente, Governador ou Prefeito), com fundamento no art. 84, IV, da CF/88 (estendido a Estados e Municípios pelo princípio da simetria), podendo ter efeitos gerais (regulamentares) ou individuais/concretos (como nomeações); já a resolução é editada por outras autoridades ou órgãos que não o chefe do Executivo (como Casas Legislativas, tribunais e agências reguladoras), sendo inclusive reconhecida como espécie normativa autônoma pelo art. 59, VII, da CF/88. Logo, o que diferencia os dois atos é quem os edita, e não a finalidade a que se destinam. Por isso, o item em questão está errado.$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,10,$q$Direito Administrativo$q$,$q$A teoria dos motivos determinantes aplica-se tanto aos atos administrativos vinculados quanto aos discricionários.$q$,$q$A teoria dos motivos determinantes aplica-se tanto aos atos administrativos vinculados quanto aos discricionários.$q$,'C',1,'under_review',true,false,$q$No julgamento do Tema Repetitivo 928, o STJ ratificou o entendimento expresso na assertiva. Segundo a teoria dos motivos determinantes, “a administração, ao adotar determinados motivos para a prática de ato administrativo, ainda que de natureza discricionária, fica a eles vinculada”.$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,11,$q$Direito Administrativo$q$,$q$Em razão do poder hierárquico, inerente à administração pública, permite-se, em caráter excepcional e por motivos relevantes devidamente justificados, a avocação permanente de competência privativa atribuída a órgão hierarquicamente inferior.$q$,$q$Em razão do poder hierárquico, inerente à administração pública, permite-se, em caráter excepcional e por motivos relevantes devidamente justificados, a avocação permanente de competência privativa atribuída a órgão hierarquicamente inferior.$q$,'E',1,'under_review',true,false,$q$A avocação é uma medida temporária e não permanente, como consta no item. Não se pode avocar uma competência privativa de um órgão. Além disso, o artigo 15 da Lei n.º 9.784/1999 regulamentou a matéria, vedando a avocação não temporária.$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,12,$q$Direito Administrativo$q$,$q$Nenhum bem público de uso especial afetado pode ser objeto de alienação.$q$,$q$Nenhum bem público de uso especial afetado pode ser objeto de alienação.$q$,'C',1,'under_review',true,false,$q$A inalienabilidade dos bens públicos afetados, de uso comum do povo e de uso especial, não é absoluta, mas relativa e condicionada, decorrendo do art. 100 do Código Civil, que os torna inalienáveis apenas enquanto conservarem sua qualificação, ou seja, enquanto estiverem afetados a uma finalidade pública (o uso coletivo ou a prestação de serviços e atividades estatais); para que possam ser alienados, é necessária a prévia desafetação, ato pelo qual o bem perde sua destinação pública e passa à categoria de bem dominical, sobre o qual incide o art. 101 do mesmo Código, que autoriza a alienação desde que observadas as exigências legais, hoje concentradas no art. 76 da Lei 14.133/2021 (interesse público justificado, avaliação prévia e, em regra, autorização legislativa e licitação para imóveis), entendimento reafirmado pelo STJ no AgRg no REsp 1.320.101/GO.$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,13,$q$Direito Administrativo$q$,$q$Na modalidade de licitação concurso, deve-se considerar vencedor o licitante que apresentar proposta de menor preço.$q$,$q$Na modalidade de licitação concurso, deve-se considerar vencedor o licitante que apresentar proposta de menor preço.$q$,'E',1,'under_review',true,false,$q$Concurso é a modalidade de licitação que busca a escolha de trabalho técnico, científico e artístico, cujo critério de julgamento será o de melhor técnica ou conteúdo artístico, havendo estipulação prévia de prêmio ou remuneração. Assim está previsto no artigo 6.º, inciso XXXIX, da Lei n.º 14.133/2021: “XXXIV – concurso: modalidade de licitação para escolha de trabalho técnico, científico ou artístico, cujo critério de julgamento será o de melhor técnica ou conteúdo artístico, e para concessão de prêmio ou remuneração ao vencedor.”$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,14,$q$Direito Administrativo$q$,$q$O controle administrativo interno é exercido no âmbito de cada um dos três Poderes, sobre os seus próprios atos e agentes.$q$,$q$O controle administrativo interno é exercido no âmbito de cada um dos três Poderes, sobre os seus próprios atos e agentes.$q$,'C',1,'under_review',true,false,$q$O fundamento desse entendimento está principalmente no art. 74 da CF/88, que obriga os Poderes Legislativo, Executivo e Judiciário a manterem, de forma integrada, sistema de controle interno, reconhecendo que, como todos exercem atividade administrativa, cada um deve fiscalizar seus próprios atos e agentes. Esse controle apoia-se no princípio da autotutela, consagrado nas Súmulas 346 e 473 do STF (poder-dever de a Administração anular seus atos ilegais e revogar os inconvenientes), e encontra suporte procedimental na Lei 9.784/99 (Lei do Processo Administrativo), notadamente no art. 1º, §1º, que estende sua aplicação aos órgãos dos Poderes Legislativo e Judiciário da União quando desempenham função administrativa, e no art. 53, que reafirma o dever de a Administração anular seus atos eivados de ilegalidade e a faculdade de revogá-los por motivo de conveniência e oportunidade.$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,15,$q$Direito Administrativo$q$,$q$Readaptação é a modalidade de investidura na qual o servidor público aposentado por invalidez retorna à ativa devido a parecer da junta médica oficial ter declarado insubsistentes os motivos da aposentadoria.$q$,$q$Readaptação é a modalidade de investidura na qual o servidor público aposentado por invalidez retorna à ativa devido a parecer da junta médica oficial ter declarado insubsistentes os motivos da aposentadoria.$q$,'E',1,'under_review',true,false,$q$Readaptação, de acordo com o art. 24 da Lei 8.112/1990, “é a investidura do servidor em cargo de atribuições e responsabilidades compatíveis com a limitação que tenha sofrido em sua capacidade física ou mental verificada em inspeção médica”. A modalidade de provimento no cargo relativa ao retorno do servidor à atividade, após ser aposentado por invalidez, em decorrência de a junta médica oficial declarar insubsistentes os motivos da aposentadoria, denomina-se, segundo a referida lei, reversão (art. 25, I).$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,16,$q$Direito Administrativo$q$,$q$Diferentemente das autarquias, a OAB não é entidade da administração indireta, portanto não se sujeita a controle hierárquico da administração pública, não estando vinculada a qualquer de suas partes.$q$,$q$Diferentemente das autarquias, a OAB não é entidade da administração indireta, portanto não se sujeita a controle hierárquico da administração pública, não estando vinculada a qualquer de suas partes.$q$,'C',1,'under_review',true,false,$q$Ao julgar o Tema de Repercussão Geral 1054, o STF fixou a seguinte tese: “O Conselho Federal e os Conselhos Seccionais da Ordem dos Advogados do Brasil não estão obrigados a prestar contas ao Tribunal de Contas da União nem a qualquer outra entidade externa”. No mesmo sentido, a ADI 3026, que firmou o entendimento de que a OAB não é entidade da administração indireta da União, não se sujeitanto a controle da administração, nem estando vinculada a qualquer de suas partes.$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,17,$q$Direito Constitucional$q$,$q$Segundo a classificação ontológica de Karl Loewenstein, constituição semântica é aquela que não limita o poder do Estado, servindo como instrumento de legitimação do regime.$q$,$q$Segundo a classificação ontológica de Karl Loewenstein, constituição semântica é aquela que não limita o poder do Estado, servindo como instrumento de legitimação do regime.$q$,'C',1,'under_review',true,false,$q$De acordo com a classificação de Karl Loewenstein (classificação ontológica), as constituições podem ser normativas, nominalistas e semânticas, sendo estas as que não limitam o poder, servindo de instrumento de legitimação do regime.$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,18,$q$Direito Constitucional$q$,$q$No Brasil, entre as limitações ao poder constituinte derivado reformador há limitações materiais implícitas, a exemplo da vedação à dupla revisão das cláusulas pétreas.$q$,$q$No Brasil, entre as limitações ao poder constituinte derivado reformador há limitações materiais implícitas, a exemplo da vedação à dupla revisão das cláusulas pétreas.$q$,'C',1,'under_review',true,false,$q$As limitações implícitas ao poder constituinte derivado reformador são aquelas não escritas, mas decorrentes da estrutura constitucional, tais como a alteração da titularidade do poder constituinte, a vedação à dupla reforma e a garantia do núcleo imodificável, segundo doutrinadores como Alexandre de Moraes, Gilmar Mendes e Paulo Gonet, Luís Roberto Barroso, Manoel Jorge Lima e Silva, entre outros.$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,19,$q$Direito Constitucional$q$,$q$Segundo a jurisprudência do STF, é possível a propositura de ação direta de inconstitucionalidade contra norma anterior à Constituição Federal de 1988.$q$,$q$Segundo a jurisprudência do STF, é possível a propositura de ação direta de inconstitucionalidade contra norma anterior à Constituição Federal de 1988.$q$,'E',1,'under_review',true,false,$q$No julgamento da ADI n.º 2, o STF assentou pela impossibilidade de ação direta de inconstitucionalidade contra norma anterior à CF, cabendo impugnação por meio de arguição de descumprimento de preceito fundamental (ADPF).$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,20,$q$Direito Constitucional$q$,$q$O controle de constitucionalidade realizado pelo Poder Judiciário é repressivo, não sendo possível, portanto, ação contra projeto de lei ainda em tramitação no Congresso Nacional.$q$,$q$O controle de constitucionalidade realizado pelo Poder Judiciário é repressivo, não sendo possível, portanto, ação contra projeto de lei ainda em tramitação no Congresso Nacional.$q$,'E',1,'under_review',true,false,$q$O STF assentou que há possibilidade de mandado de segurança impetrado por parlamentar para impugnar projeto de lei que viole cláusula pétrea, em face do disposto no § 4.º do artigo 60 da CF, segundo o qual não será objeto de deliberação a proposta de emenda tendente a abolir: I – a forma federativa de Estado; II – o voto direto, secreto, universal e periódico; III – a separação dos Poderes; IV – os direitos e garantias individuais. Nesse sentido, MS 22.503/DF e MS 20.257/DF.$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,21,$q$Direito Constitucional$q$,$q$Em atenção ao princípio do efeito integrador, deve-se dar à Constituição o sentido que lhe confira maior eficácia, com vistas à garantia de um sistema unitário de normas e princípios.$q$,$q$Em atenção ao princípio do efeito integrador, deve-se dar à Constituição o sentido que lhe confira maior eficácia, com vistas à garantia de um sistema unitário de normas e princípios.$q$,'E',1,'under_review',true,false,$q$De acordo com a doutrina, o princípio do efeito integrador significa que “na resolução de problemas jurídico-constitucionais deve dar-se primazia aos critérios ou pontos de vista que favoreçam a integração política e social e o reforço à unidade política”. O princípio que visa dar a maior eficácia à Constituição é denominado de “princípio da máxima efetividade”.$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,22,$q$Direito Constitucional$q$,$q$Para fins de proteção jurídica da inviolabilidade domiciliar, o conceito de casa revela-se abrangente e, por isso, estende-se a qualquer aposento de habitação coletiva, desde que ocupado, compreendendo os quartos de hotel.$q$,$q$Para fins de proteção jurídica da inviolabilidade domiciliar, o conceito de casa revela-se abrangente e, por isso, estende-se a qualquer aposento de habitação coletiva, desde que ocupado, compreendendo os quartos de hotel.$q$,'C',1,'under_review',true,false,$q$No RHC 90.376, o STF assentou o seguinte: “Para os fins da proteção jurídica a que se refere o art. 5.º, XI, da CF, o conceito normativo de “casa” revela-se abrangente e, por estender-se a qualquer aposento de habitação coletiva, desde que ocupado (CP, art. 150, § 4.º, II), compreende, observada essa específica limitação espacial, os quartos de hotel.”$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,23,$q$Direito Constitucional$q$,$q$Conforme entendimento do STF, há possibilidade de as entidades de classe utilizarem o mandado de injunção coletivo, desde que sejam legalmente constituídas e estejam em funcionamento há pelo menos um ano.$q$,$q$Conforme entendimento do STF, há possibilidade de as entidades de classe utilizarem o mandado de injunção coletivo, desde que sejam legalmente constituídas e estejam em funcionamento há pelo menos um ano.$q$,'X',1,'annulled',true,false,$q$No MI 472 e MI 4.503-AGR, o STF assim assentou: “A jurisprudência desta Corte sedimentou a possibilidade de as entidades de classe, desde que legalmente constituídas e em funcionamento há pelo menos um ano, utilizarem o mandado de injunção coletivo.”$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,24,$q$Direito Constitucional$q$,$q$O STF adota a teoria do bloco de constitucionalidade, de sorte que os tratados internacionais sobre direitos humanos, independentemente da forma de sua aprovação, gozam de força constitucional.$q$,$q$O STF adota a teoria do bloco de constitucionalidade, de sorte que os tratados internacionais sobre direitos humanos, independentemente da forma de sua aprovação, gozam de força constitucional.$q$,'E',1,'under_review',true,false,$q$No julgamento do HC 87.585 e do RE 466.343, ao julgar previsão do Pacto de São José da Costa Rica, o STF assentou que os tratados internacionais sobre direitos humanos que não forem aprovados em dois turnos, por dois terços, em casa uma das Casas Legislativas, terão força supralegal, mas não constitucional.$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,25,$q$Direito Constitucional$q$,$q$Dada a competência legislativa concorrente entre União, Distrito Federal e estados, a superveniência de lei federal sobre normas gerais revoga a lei estadual no que lhe seja contrário.$q$,$q$Dada a competência legislativa concorrente entre União, Distrito Federal e estados, a superveniência de lei federal sobre normas gerais revoga a lei estadual no que lhe seja contrário.$q$,'E',1,'under_review',true,false,$q$O § 4.º do artigo 24 da CF estabelece que a “superveniência de lei federal sobre normas gerais suspende a eficácia da lei estadual, no que lhe for contrário”; assim, há suspensão da eficácia, e não revogação da lei estadual.$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,26,$q$Direito Constitucional$q$,$q$São atribuídas ao Distrito Federal as competências legislativas reservadas aos estados e municípios.$q$,$q$São atribuídas ao Distrito Federal as competências legislativas reservadas aos estados e municípios.$q$,'C',1,'under_review',true,false,$q$O § 1.º do artigo 32 da CF estabelece que: “Ao Distrito Federal são atribuídas as competências legislativas reservadas aos Estados e Municípios.”$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,27,$q$Direito Constitucional$q$,$q$Em razão da competência legislativa suplementar dos estados em relação ao respectivo regime próprio de previdência social (RPPS), lei estadual pode ampliá-lo aos servidores ocupantes de cargo em comissão, desde que haja a respectiva contribuição.$q$,$q$Em razão da competência legislativa suplementar dos estados em relação ao respectivo regime próprio de previdência social (RPPS), lei estadual pode ampliá-lo aos servidores ocupantes de cargo em comissão, desde que haja a respectiva contribuição.$q$,'E',1,'under_review',true,false,$q$No julgamento da ADI 7.683, rel. Ministro Cristiano Zanin, o STF assim decidiu: “A jurisprudência do Supremo Tribunal Federal é consolidada no sentido de que a competência legislativa suplementar dos estados em relação ao respectivo regime próprio deve mantê-lo restrito aos servidores titulares de cargo efetivo, não havendo permissão constitucional para ampliar o rol previsto no art. 40 da Constituição Federal.”$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,28,$q$Direito Constitucional$q$,$q$Comissão parlamentar de inquérito não pode determinar busca e apreensão domiciliar ante a cláusula de reserva de jurisdição, podendo ordenar, entretanto, busca e apreensão de bens, objetos e computadores, desde que essa diligência não se efetive em local inviolável.$q$,$q$Comissão parlamentar de inquérito não pode determinar busca e apreensão domiciliar ante a cláusula de reserva de jurisdição, podendo ordenar, entretanto, busca e apreensão de bens, objetos e computadores, desde que essa diligência não se efetive em local inviolável.$q$,'C',1,'under_review',true,false,$q$No julgamento do MS 33.663 MC, o STF assim assentou: “Impossibilidade jurídica de CPI praticar atos sobre os quais incida a cláusula constitucional da reserva de jurisdição, como a busca e apreensão domiciliar (...). Possibilidade, contudo, de a CPI ordenar busca e apreensão de bens, objetos e computadores, desde que essa diligência não se efetive em local inviolável, como os espaços domiciliares, sob pena, em tal hipótese, de invalidade da diligência e de ineficácia probatória dos elementos informativos dela resultantes. Deliberação da CPI/Petrobras que, embora não abrangente do domicílio dos impetrantes, ressentir-se-ia da falta da necessária fundamentação substancial. Ausência de indicação, na espécie, de causa provável e de fatos concretos que, se presentes, autorizariam a medida excepcional da busca e apreensão, mesmo a de caráter não domiciliar.”$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,29,$q$Direito Constitucional$q$,$q$É constitucional a previsão, em lei estadual, de que a nomeação de delegado de polícia no cargo em comissão de chefe de polícia recaia sobre o delegado que esteja posicionado na classe mais elevada da carreira.$q$,$q$É constitucional a previsão, em lei estadual, de que a nomeação de delegado de polícia no cargo em comissão de chefe de polícia recaia sobre o delegado que esteja posicionado na classe mais elevada da carreira.$q$,'X',1,'annulled',true,false,$q$Na ADI 3.062, o STF assim decidiu: “Nomeação de chefe de Polícia. Exigência de que o indicado seja não só delegado de carreira – como determinado pela CF – como também que esteja na classe mais elevada. Inexistência de vício de iniciativa. Revisão jurisprudencial, em prol do princípio federativo, conforme ao art. 24, XVI, da CF. Possibilidade de os Estados disciplinarem os critérios de acesso ao cargo de confiança, desde que respeitado o mínimo constitucional. Critério que não só se coaduna com a exigência constitucional como também a reforça, por subsidiar o adequado exercício da função e valorizar os quadros da carreira.”$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,30,$q$Direito Constitucional$q$,$q$O rol de órgãos encarregados do exercício da segurança pública é taxativo, devendo o modelo federal ser observado pelos estados-membros e pelo Distrito Federal.$q$,$q$O rol de órgãos encarregados do exercício da segurança pública é taxativo, devendo o modelo federal ser observado pelos estados-membros e pelo Distrito Federal.$q$,'C',1,'under_review',true,false,$q$Nas ADI 2.287, ADI 1.182, ADI 2.575, o STF assim assentou: (...) “o rol de órgãos encarregados do exercício da segurança pública, previsto no art. 144, I a V, da CF, é taxativo e (...) esse modelo federal deve ser observado pelos estados-membros e pelo Distrito Federal.”$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,31,$q$Legislação de Segurança Pública$q$,$q$A Política Nacional de Segurança Pública e Defesa Social será estabelecida no âmbito do Sistema Único de Segurança Pública em ato conjunto da União, dos estados, do Distrito Federal e dos municípios, observadas as diretrizes estabelecidas conjuntamente.$q$,$q$A Política Nacional de Segurança Pública e Defesa Social será estabelecida no âmbito do Sistema Único de Segurança Pública em ato conjunto da União, dos estados, do Distrito Federal e dos municípios, observadas as diretrizes estabelecidas conjuntamente.$q$,'X',1,'annulled',true,false,$q$Segundo o art. 3.º da Lei n.º 13.675/2018, “Compete à União estabelecer a Política Nacional de Segurança Pública e Defesa Social (PNSPDS) e aos Estados, ao Distrito Federal e aos Municípios estabelecer suas respectivas políticas, observadas as diretrizes da política nacional, especialmente para análise e enfrentamento dos riscos à harmonia da convivência social, com destaque às situações de emergência e aos crimes interestaduais e transnacionais.”$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,32,$q$Legislação de Segurança Pública$q$,$q$O Conselho Superior de Polícia Civil, presidido pelo delegado-geral, é composto exclusivamente por delegados da polícia civil em atividade da classe mais elevada do cargo.$q$,$q$O Conselho Superior de Polícia Civil, presidido pelo delegado-geral, é composto exclusivamente por delegados da polícia civil em atividade da classe mais elevada do cargo.$q$,'E',1,'under_review',true,false,$q$De acordo com o art. 9.º da Lei n.º 14.735/2023, “O Conselho Superior de Polícia Civil, presidido pelo Delegado-Geral e integrado por policiais civis, é composto por representantes de todos os cargos efetivos da corporação, com a possibilidade de eleição de seus membros e participação paritária, respeitada a lei do respectivo ente federativo.”$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,33,$q$Direito Administrativo$q$,$q$A decisão administrativa, controladora ou judicial fundada exclusivamente em valores jurídicos abstratos deverá indicar as consequências práticas da decisão e demonstrar a necessidade e a adequação da medida imposta, consideradas as possíveis alternativas e observados os critérios de proporcionalidade e razoabilidade.$q$,$q$A decisão administrativa, controladora ou judicial fundada exclusivamente em valores jurídicos abstratos deverá indicar as consequências práticas da decisão e demonstrar a necessidade e a adequação da medida imposta, consideradas as possíveis alternativas e observados os critérios de proporcionalidade e razoabilidade.$q$,'C',1,'under_review',true,false,$q$De acordo com os artigos 2.º e 3.º do Decreto n.º 9.830/2019, a decisão baseada exclusivamente em valores jurídicos abstratos deverá ser motivada de forma argumentativa, com indicação das consequências práticas da decisão, bem como da necessidade e adequação da medida adotada, consideradas as possíveis alternativas e observados os critérios de proporcionalidade e razoabilidade.$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,34,$q$Direito Administrativo$q$,$q$Nas esferas administrativa, controladora e judicial, a invalidação de ato, contrato, ajuste, processo ou norma administrativa prescinde da análise das consequências práticas da decisão.$q$,$q$Nas esferas administrativa, controladora e judicial, a invalidação de ato, contrato, ajuste, processo ou norma administrativa prescinde da análise das consequências práticas da decisão.$q$,'E',1,'under_review',true,false,$q$O artigo 20 da Lei de Introdução às Normas do Direito Brasileiro (LINDB) exige que, nas esferas administrativa, controladora e judicial, sejam consideradas as consequências práticas da decisão antes da invalidação de atos, contratos, ajustes, processos ou normas administrativas.$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,35,$q$Direito Administrativo$q$,$q$A decisão administrativa que decretar a invalidação de ato administrativo deverá indicar, quando for o caso, as condições para que a regularização do ato ocorra de modo proporcional e equânime, sem impor ônus ou perdas anormais aos atingidos.$q$,$q$A decisão administrativa que decretar a invalidação de ato administrativo deverá indicar, quando for o caso, as condições para que a regularização do ato ocorra de modo proporcional e equânime, sem impor ônus ou perdas anormais aos atingidos.$q$,'C',1,'under_review',true,false,$q$O art. 21 da Lei de Introdução às Normas do Direito Brasileiro (LINDB) prevê expressamente a necessidade de indicação de condições de regularização proporcionais, equânimes e aptas a evitar ônus ou perdas anormais aos atingidos pela decisão de invalidação de ato administrativo.$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,36,$q$Direito Civil$q$,$q$A existência legal da pessoa natural termina com a morte, presumindo-se esta, quanto aos ausentes, nos casos em que a lei autoriza a abertura de sucessão definitiva.$q$,$q$A existência legal da pessoa natural termina com a morte, presumindo-se esta, quanto aos ausentes, nos casos em que a lei autoriza a abertura de sucessão definitiva.$q$,'C',1,'under_review',true,false,$q$De acordo com o art. 6.º do Código Civil, a “existência da pessoa natural termina com a morte; presume-se esta, quanto aos ausentes, nos casos em que a lei autoriza a abertura de sucessão definitiva.”$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,37,$q$Direito Civil$q$,$q$Considerado o mesmo que anonimato, o pseudônimo utilizado para atividades lícitas não goza da mesma proteção conferida ao nome civil da pessoa natural.$q$,$q$Considerado o mesmo que anonimato, o pseudônimo utilizado para atividades lícitas não goza da mesma proteção conferida ao nome civil da pessoa natural.$q$,'E',1,'under_review',true,false,$q$O art. 19 do Código Civil estabelece expressamente que o pseudônimo adotado para atividades lícitas goza da proteção conferida ao nome. Além disso, pseudônimo não se confunde com anonimato, já que consiste em identificação pública adotada pela pessoa para determinados fins.$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,38,$q$Direito Civil$q$,$q$O domicílio da pessoa que dispuser de várias residências será obrigatoriamente o local em que permaneça com maior habitualidade ou no qual esteja situada sua principal atividade econômica.$q$,$q$O domicílio da pessoa que dispuser de várias residências será obrigatoriamente o local em que permaneça com maior habitualidade ou no qual esteja situada sua principal atividade econômica.$q$,'E',1,'under_review',true,false,$q$Segundo o art. 71 do Código Civil, se a pessoa natural tiver diversas residências onde alternadamente viva, qualquer delas poderá ser considerada seu domicílio.$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,39,$q$Direito Civil$q$,$q$O silêncio importa anuência quando as circunstâncias ou os usos o autorizarem e não for necessária declaração de vontade expressa.$q$,$q$O silêncio importa anuência quando as circunstâncias ou os usos o autorizarem e não for necessária declaração de vontade expressa.$q$,'C',1,'under_review',true,false,$q$A assertiva corresponde ao disposto no art. 111 do Código Civil: “O silêncio importa anuência, quando as circunstâncias ou os usos o autorizarem, e não for necessária a declaração de vontade expressa.”$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,40,$q$Direito Civil$q$,$q$O negócio jurídico celebrado mediante coação é nulo de pleno direito, não se admitindo confirmação posterior pelas partes.$q$,$q$O negócio jurídico celebrado mediante coação é nulo de pleno direito, não se admitindo confirmação posterior pelas partes.$q$,'E',1,'under_review',true,false,$q$A coação constitui causa de anulabilidade do negócio jurídico, nos termos do art. 171, II, do Código Civil, sendo possível sua confirmação nas hipóteses legais.$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,41,$q$Direito Civil$q$,$q$A indenização pela publicação não autorizada da imagem de pessoa para fins econômicos ou comerciais independe da demonstração de prejuízo.$q$,$q$A indenização pela publicação não autorizada da imagem de pessoa para fins econômicos ou comerciais independe da demonstração de prejuízo.$q$,'C',1,'under_review',true,false,$q$O STJ consolidou o entendimento de que o uso não autorizado da imagem de pessoa para fins econômicos ou comerciais gera dano moral in re ipsa, dispensando-se prova do prejuízo, conforme a Súmula 403 do STJ.$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,42,$q$Direito Civil$q$,$q$A prescrição pode ser alegada em qualquer grau de jurisdição pela parte a quem aproveita.$q$,$q$A prescrição pode ser alegada em qualquer grau de jurisdição pela parte a quem aproveita.$q$,'C',1,'under_review',true,false,$q$O art. 193 do Código Civil dispõe que a prescrição pode ser alegada em qualquer grau de jurisdição pela parte a quem aproveita.$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,43,$q$Direito Civil$q$,$q$É anulável a renúncia das partes à decadência legal após a sua consumação.$q$,$q$É anulável a renúncia das partes à decadência legal após a sua consumação.$q$,'E',1,'under_review',true,false,$q$Conforme o art. 209 do Código Civil, é “nula a renúncia à decadência fixada em lei”.$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,44,$q$Direito Civil$q$,$q$O possuidor de má-fé responde pela perda ou deterioração da coisa, ainda que acidentais, salvo se provar que de igual modo teriam ocorrido se a coisa estivesse na posse do reivindicante.$q$,$q$O possuidor de má-fé responde pela perda ou deterioração da coisa, ainda que acidentais, salvo se provar que de igual modo teriam ocorrido se a coisa estivesse na posse do reivindicante.$q$,'C',1,'under_review',true,false,$q$A assertiva corresponde ao regime previsto no art. 1.218 do Código Civil: “Art. 1.218. O possuidor de má-fé responde pela perda, ou deterioração da coisa, ainda que acidentais, salvo se provar que de igual modo se teriam dado, estando ela na posse do reivindicante.”$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,45,$q$Direito Civil$q$,$q$A boa-fé do adquirente impede, por si só, o reconhecimento da inexistência da propriedade sobre o veículo adquirido de quem não era verdadeiro proprietário.$q$,$q$A boa-fé do adquirente impede, por si só, o reconhecimento da inexistência da propriedade sobre o veículo adquirido de quem não era verdadeiro proprietário.$q$,'E',1,'under_review',true,false,$q$Nos termos do art. 1.268 do Código Civil, a tradição realizada por quem não é proprietário não transfere validamente a propriedade, salvo hipóteses legais excepcionais. Segundo entendimento do STJ, a boa-fé do adquirente, por si só, não impede a restituição do veículo ao verdadeiro proprietário, conforme decidido no AREsp 1.367.105/SP, Rel. min. Paulo de Tarso Sanseverino, publicado em 26/11/2018.$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,46,$q$Direito Civil$q$,$q$A utilização da pessoa jurídica exclusivamente para ocultação patrimonial e prática reiterada de fraudes contra credores autoriza a desconsideração da personalidade jurídica, que alcança automaticamente o patrimônio de todos os sócios da sociedade empresária.$q$,$q$A utilização da pessoa jurídica exclusivamente para ocultação patrimonial e prática reiterada de fraudes contra credores autoriza a desconsideração da personalidade jurídica, que alcança automaticamente o patrimônio de todos os sócios da sociedade empresária.$q$,'E',1,'under_review',true,false,$q$O art. 50 do Código Civil estabelece que a desconsideração da personalidade jurídica alcança os bens particulares dos administradores ou sócios beneficiados direta ou indiretamente pelo abuso, não havendo extensão automática a todos os sócios da sociedade empresária.$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,47,$q$Direito Empresarial$q$,$q$Os denunciados por crime falimentar podem exercer atividade empresarial e atuar como administradores de sociedade empresária.$q$,$q$Os denunciados por crime falimentar podem exercer atividade empresarial e atuar como administradores de sociedade empresária.$q$,'C',1,'under_review',true,false,$q$A restrição ao exercício da atividade empresarial, oriunda da aplicação de pena, ainda que temporariamente, tem por requisito o ato da condenação. É o que preceitua o art. 1.011, § 1.º, do Código Civil, segundo o qual não podem ser administradores, além das pessoas impedidas por lei especial, os condenados a pena que vede, ainda que temporariamente, o acesso a cargos públicos; ou por crime falimentar \[...\], enquanto perdurarem os efeitos da condenação.$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,48,$q$Direito Empresarial$q$,$q$O sócio oculto não poderá ser responsabilizado, inclusive perante terceiros, ainda que se beneficie das atividades da empresa, uma vez que não é formalmente registrado no ato constitutivo.$q$,$q$O sócio oculto não poderá ser responsabilizado, inclusive perante terceiros, ainda que se beneficie das atividades da empresa, uma vez que não é formalmente registrado no ato constitutivo.$q$,'E',1,'under_review',true,false,$q$A doutrina majoritária entende que o sócio oculto pode ser responsabilizado quando sua atuação se revela essencial à prática do ato ilícito, ou quando se beneficia diretamente da fraude contra terceiros. Nesse sentido, o STJ tem entendido que é possível responsabilizar o sócio oculto que, embora não formalmente registrado, se beneficia das atividades da empresa, inclusive em prejuízo de terceiros, caracterizando-se abuso da forma societária. (STJ, REsp 2.055.325/MG, Rel. Min. Nancy Andrighi, j. 12/09/2023).$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,49,$q$Direito Empresarial$q$,$q$Nas sociedades em nome coletivo, todos os sócios respondem solidária e ilimitadamente pelas obrigações sociais, podendo eles, no ato constitutivo, limitar entre si a responsabilidade de cada um.$q$,$q$Nas sociedades em nome coletivo, todos os sócios respondem solidária e ilimitadamente pelas obrigações sociais, podendo eles, no ato constitutivo, limitar entre si a responsabilidade de cada um.$q$,'C',1,'under_review',true,false,$q$De acordo com o art. 1.039 do Código Civil, “somente pessoas físicas podem tomar parte na sociedade em nome coletivo, respondendo todos os sócios, solidária e ilimitadamente, pelas obrigações sociais. Parágrafo único. Sem prejuízo da responsabilidade perante terceiros, podem os sócios, no ato constitutivo, ou por unânime convenção posterior, limitar entre si a responsabilidade de cada um”.$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,50,$q$Direito Empresarial$q$,$q$O estabelecimento empresarial compreende todo o complexo de bens organizado para o exercício da empresa por empresário ou por sociedade empresária.$q$,$q$O estabelecimento empresarial compreende todo o complexo de bens organizado para o exercício da empresa por empresário ou por sociedade empresária.$q$,'C',1,'under_review',true,false,$q$Conforme dispõe o art. 1.142 do Código Civil, “considera-se estabelecimento todo complexo de bens organizado, para exercício da empresa, por empresário, ou por sociedade empresária”.$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,51,$q$Direito Empresarial$q$,$q$A empresa de pequeno porte e a sociedade unipessoal dispõem de tratamento especial e diferenciado no que diz respeito à inscrição no registro de empresas.$q$,$q$A empresa de pequeno porte e a sociedade unipessoal dispõem de tratamento especial e diferenciado no que diz respeito à inscrição no registro de empresas.$q$,'E',1,'under_review',true,false,$q$A classificação de empresa de pequeno porte (EPP) é determinada na Lei Complementar n.º 123/2006 para fins de encargos tributários e outras providências, não se confundindo com o tipo empresarial. A sociedade unipessoal, por sua vez, é figura jurídica estabelecida pela Lei n.º 13.874/2019, que permite a constituição de sociedade por sócio único. O art. 970 do Código Civil flexibiliza o regramento para o registro empresarial em situações específicas, prevendo tratamento favorecido, diferenciado e simplificado para o empresário rural e o pequeno empresário, quanto à inscrição e aos efeitos daí decorrentes.$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,52,$q$Direito Empresarial$q$,$q$As despesas que os credores fizerem para tomar parte na recuperação judicial, via de regra, não serão exigíveis do devedor.$q$,$q$As despesas que os credores fizerem para tomar parte na recuperação judicial, via de regra, não serão exigíveis do devedor.$q$,'C',1,'under_review',true,false,$q$O art. 5.º da Lei n.º 11.101/2005 prevê que “não são exigíveis do devedor, na recuperação judicial ou na falência: I – as obrigações a título gratuito; II – as despesas que os credores fizerem para tomar parte na recuperação judicial ou na falência, salvo as custas judiciais decorrentes de litígio com o devedor”.$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,53,$q$Direito Empresarial$q$,$q$A alienação de bens prevista em plano de recuperação judicial caracteriza hipótese de decretação da falência.$q$,$q$A alienação de bens prevista em plano de recuperação judicial caracteriza hipótese de decretação da falência.$q$,'E',1,'under_review',true,false,$q$Considera-se causa de falência a prática de atos fraudulentos ou simulados com o objetivo de prejudicar credores ou retardar pagamentos (Lei n.º 11.101/2005, art. 94, III). A alienação, ou liquidação de ativos, prevista no plano de recuperação é lícita e autorizada pela lei, não sendo causa de falência, diferentemente do que ocorre quando da liquidação precipitada de ativos (art. 94, III, a).$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,54,$q$Direito Empresarial$q$,$q$Como garantia da livre iniciativa nacional, deve a administração pública redigir enunciados que impeçam a entrada de novos competidores estrangeiros no mercado brasileiro.$q$,$q$Como garantia da livre iniciativa nacional, deve a administração pública redigir enunciados que impeçam a entrada de novos competidores estrangeiros no mercado brasileiro.$q$,'E',1,'under_review',true,false,$q$O art. 4.º da Lei n.º 13.874/2019 estabelece que “é dever da administração pública e das demais entidades que se vinculam a essa lei, no exercício de regulamentação de norma pública pertencente à legislação sobre a qual a lei versa, exceto se em estrito cumprimento a previsão explícita em lei, evitar o abuso do poder regulatório de maneira a, indevidamente: \[...\] II - redigir enunciados que impeçam a entrada de novos competidores nacionais ou estrangeiros no mercado”.$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,55,$q$Direito Penal$q$,$q$A conduta de Mário, ao abrir a sala e possibilitar a subtração da obra de arte, não é punível, pois ele agiu sob coação moral irresistível, o que exclui sua culpabilidade, devendo responder pelo crime apenas o autor da coação.$q$,$q$A conduta de Mário, ao abrir a sala e possibilitar a subtração da obra de arte, não é punível, pois ele agiu sob coação moral irresistível, o que exclui sua culpabilidade, devendo responder pelo crime apenas o autor da coação.$q$,'C',1,'under_review',true,false,$q$De acordo com o Código Penal, se o fato é cometido sob coação irresistível, só é punível o autor da coação. A grave ameaça de morte exercida contra a esposa do vigilante configurou uma coação moral irresistível, circunstância que afasta a exigibilidade de conduta diversa (elemento da culpabilidade), isentando Mário de pena. Este é o teor do art. 22 do CP: “Se o fato é cometido sob coação irresistível ou em estrita obediência a ordem, não manifestamente ilegal, de superior hierárquico, só é punível o autor da coação ou da ordem.”$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,56,$q$Direito Penal$q$,$q$No que se refere à morte da pedestre Helena, Roberto responderá por homicídio culposo, uma vez que não tinha a intenção de matá-la, configurando-se resultado diverso do pretendido.$q$,$q$No que se refere à morte da pedestre Helena, Roberto responderá por homicídio culposo, uma vez que não tinha a intenção de matá-la, configurando-se resultado diverso do pretendido.$q$,'E',1,'under_review',true,false,$q$A situação descrita configura erro na execução, e não “resultado diverso do pretendido”. Segundo o art. 73 do Código Penal, quando o agente, por erro no uso dos meios de execução, atinge pessoa diversa da que pretendia ofender, ele responde como se tivesse praticado o crime contra a pessoa que efetivamente pretendia atingir. Portanto, Roberto responderá pelo crime de homicídio doloso consumado contra Helena, consideradas as qualidades de seu alvo original, que era Lúcio.$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,57,$q$Direito Penal$q$,$q$A devolução voluntária e intacta da obra de arte por Roberto, ocorrida antes do recebimento da denúncia, configura arrependimento posterior, o que lhe assegura a redução da pena de um a dois terços em relação ao crime contra o patrimônio.$q$,$q$A devolução voluntária e intacta da obra de arte por Roberto, ocorrida antes do recebimento da denúncia, configura arrependimento posterior, o que lhe assegura a redução da pena de um a dois terços em relação ao crime contra o patrimônio.$q$,'E',1,'under_review',true,false,$q$Para a incidência do arrependimento posterior, a lei exige que o crime tenha sido cometido sem violência ou grave ameaça à pessoa (Código Penal, art. 16). Como o crime patrimonial cometido por Roberto envolveu o emprego de arma de fogo e grave ameaça à família do vigilante, é incabível a aplicação do arrependimento posterior, mesmo que a coisa tenha sido restituída voluntariamente antes do recebimento da denúncia.$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,58,$q$Direito Penal$q$,$q$Ainda que, em hipótese processual bastante favorável, Roberto viesse a ser condenado a pena privativa de liberdade não superior a 4 anos, o juiz estaria legalmente impedido de substituí-la por penas restritivas de direitos.$q$,$q$Ainda que, em hipótese processual bastante favorável, Roberto viesse a ser condenado a pena privativa de liberdade não superior a 4 anos, o juiz estaria legalmente impedido de substituí-la por penas restritivas de direitos.$q$,'C',1,'under_review',true,false,$q$A substituição da pena só é admitida nos casos em que não há emprego de violência ou grave ameaça à pessoa, conforme art. 44, I, do Código Penal.$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,59,$q$Direito Penal$q$,$q$A conduta de Joaquim contra Beatriz, caracterizada por perseguição contumaz, vigilância constante e insultos com o objetivo de controlar as ações da ex-namorada e causar-lhe dano emocional, configura, nos termos da Lei n.º 11.340/2006, violência moral contra a mulher.$q$,$q$A conduta de Joaquim contra Beatriz, caracterizada por perseguição contumaz, vigilância constante e insultos com o objetivo de controlar as ações da ex-namorada e causar-lhe dano emocional, configura, nos termos da Lei n.º 11.340/2006, violência moral contra a mulher.$q$,'E',1,'under_review',true,false,$q$Não se trata de violência moral, mas de violência psicológica. O art. 7.º, II, da Lei n.º 11.340/2006 estabelece expressamente como forma de violência contra a mulher a violência psicológica, que é entendida como qualquer conduta que cause dano emocional e diminuição da autoestima, ou que vise degradar ou controlar ações e comportamentos mediante ameaça, constrangimento, humilhação, manipulação, isolamento, vigilância constante, perseguição contumaz, insulto, entre outros meios.$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,60,$q$Direito Penal$q$,$q$Pelo fato de a arma de fogo ter sido encontrada guardada no interior da residência de Joaquim, este responderá, de acordo com a Lei n.º 10.826/2003, pelo crime de posse irregular de arma de fogo de uso permitido, visto que a posse intramuros afasta a configuração dos crimes mais graves relacionados a armamento de uso restrito.$q$,$q$Pelo fato de a arma de fogo ter sido encontrada guardada no interior da residência de Joaquim, este responderá, de acordo com a Lei n.º 10.826/2003, pelo crime de posse irregular de arma de fogo de uso permitido, visto que a posse intramuros afasta a configuração dos crimes mais graves relacionados a armamento de uso restrito.$q$,'E',1,'under_review',true,false,$q$A arma de fogo com numeração suprimida é equiparada à de uso proibido e, por isso, o crime praticado é o previsto no art. 16, § 1º, IV, da Lei n.º 10.826/2003.$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,61,$q$Direito Penal$q$,$q$Se ficar comprovado que Joaquim praticou o delito de tráfico de drogas tendo-se aproveitado do exercício da função pública, incidirá causa especial de aumento de pena prevista na Lei n.º 11.343/2006.$q$,$q$Se ficar comprovado que Joaquim praticou o delito de tráfico de drogas tendo-se aproveitado do exercício da função pública, incidirá causa especial de aumento de pena prevista na Lei n.º 11.343/2006.$q$,'C',1,'under_review',true,false,$q$Conforme art. 40 da Lei n. º 11.343/2006: “As penas previstas nos arts. 33 a 37 desta Lei são aumentadas de um sexto a dois terços, se: (...) II - o agente praticar o crime prevalecendo-se de função pública ou no desempenho de missão de educação, poder familiar, guarda ou vigilância; (...).$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,62,$q$Direito Penal$q$,$q$A circunstância que agrava a pena em razão de o agente cometer o crime prevalecendo-se de relações domésticas ou com violência contra a mulher, conforme disposto na Lei n.º 11.340/2006, ostenta natureza estritamente objetiva, atinente ao modo de execução do delito e, por consequência legal, havendo concurso de pessoas, essa agravante se comunicará de forma incondicional a todos os coautores e partícipes, com fulcro na regra geral de comunicabilidade das circunstâncias.$q$,$q$A circunstância que agrava a pena em razão de o agente cometer o crime prevalecendo-se de relações domésticas ou com violência contra a mulher, conforme disposto na Lei n.º 11.340/2006, ostenta natureza estritamente objetiva, atinente ao modo de execução do delito e, por consequência legal, havendo concurso de pessoas, essa agravante se comunicará de forma incondicional a todos os coautores e partícipes, com fulcro na regra geral de comunicabilidade das circunstâncias.$q$,'E',1,'under_review',true,false,$q$O Código Penal estabelece no art. 30 que não se comunicam as circunstâncias e as condições de caráter pessoal, salvo quando elementares do crime. A agravante genérica prevista no art. 61, II, alínea f, atinente à violência contra a mulher prevista na Lei Maria da Penha ou prevalecimento de relações domésticas, possui caráter subjetivo, razão pela qual não se estende aos coautores ou partícipes do delito.$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,63,$q$Direito Penal$q$,$q$De acordo com o Código Penal, o desconhecimento da lei é inescusável, mas o erro sobre a ilicitude do fato, se plenamente inevitável nas circunstâncias, afasta a responsabilidade penal, isentando o agente de pena.$q$,$q$De acordo com o Código Penal, o desconhecimento da lei é inescusável, mas o erro sobre a ilicitude do fato, se plenamente inevitável nas circunstâncias, afasta a responsabilidade penal, isentando o agente de pena.$q$,'C',1,'under_review',true,false,$q$Esse é o teor do art. 21 do Código Penal: “O desconhecimento da lei é inescusável. O erro sobre a ilicitude do fato, se inevitável, isenta de pena; se evitável, poderá diminuí-la de um sexto a um terço.”$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,64,$q$Direito Penal$q$,$q$Conforme o microssistema de proteção contra o abuso de autoridade (Lei n.º 13.869/2019), a fixação na sentença do valor mínimo para reparação dos danos causados pela infração é considerada um efeito automático da condenação, devendo o juiz estabelecer esse montante indenizatório de ofício, de forma a tutelar de imediato o interesse público lesionado pela autoridade.$q$,$q$Conforme o microssistema de proteção contra o abuso de autoridade (Lei n.º 13.869/2019), a fixação na sentença do valor mínimo para reparação dos danos causados pela infração é considerada um efeito automático da condenação, devendo o juiz estabelecer esse montante indenizatório de ofício, de forma a tutelar de imediato o interesse público lesionado pela autoridade.$q$,'E',1,'under_review',true,false,$q$O art. 4.º da Lei n.º 13.869/2019 exige o requerimento da parte interessada como pressuposto da fixação de reparação de danos: “São efeitos da condenação: I - tornar certa a obrigação de indenizar o dano causado pelo crime, devendo o juiz, a requerimento do ofendido, fixar na sentença o valor mínimo para reparação dos danos causados pela infração, considerando os prejuízos por ele sofridos.” E, de acordo com o parágrafo único do mesmo artigo, o efeito de fixação na sentença do valor mínimo para reparação de danos não é um efeito automático, devendo ser declarado motivadamente em sentença.$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,65,$q$Direito Penal$q$,$q$O arrependimento posterior, causa obrigatória de diminuição de pena aplicável, ostenta natureza jurídica de circunstância objetiva e, por essa razão, caso o delito seja praticado em concurso de pessoas, a reparação do dano efetuada de maneira voluntária por apenas um dos corréus implicará a extensão da minorante a todos os demais coautores e partícipes.$q$,$q$O arrependimento posterior, causa obrigatória de diminuição de pena aplicável, ostenta natureza jurídica de circunstância objetiva e, por essa razão, caso o delito seja praticado em concurso de pessoas, a reparação do dano efetuada de maneira voluntária por apenas um dos corréus implicará a extensão da minorante a todos os demais coautores e partícipes.$q$,'C',1,'under_review',true,false,$q$De acordo com o art. 30 do Código Penal, “Não se comunicam as circunstâncias e as condições de caráter pessoal, salvo quando elementares do crime.” A interpretação do referido artigo, segunda a doutrina, autoriza a conclusão de que a causa de diminuição de pena se comunica entre aquele que efetivamente se responsabilizou em reparar o dano e aqueles que não o fizeram.$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,66,$q$Direito Penal$q$,$q$No cálculo da sanção penal em casos de concurso formal de crimes, o legislador instituiu expressamente uma exceção ao sistema de exasperação no que se refere à pena de multa: as penas pecuniárias cominadas a cada delito devem ser aplicadas de forma distinta e integral.$q$,$q$No cálculo da sanção penal em casos de concurso formal de crimes, o legislador instituiu expressamente uma exceção ao sistema de exasperação no que se refere à pena de multa: as penas pecuniárias cominadas a cada delito devem ser aplicadas de forma distinta e integral.$q$,'C',1,'under_review',true,false,$q$A regra positivada no art. 72 do Código Penal determina que “No concurso de crimes, as penas de multa são aplicadas distinta e integralmente”, o que atrai, para a sanção pecuniária, o sistema do cúmulo material, afastando a exasperação.$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,67,$q$Direito Penal$q$,$q$Em se tratando do delito de lesão corporal culposa na direção de veículo automotor, ainda que praticado sob influência de álcool ou substância psicoativa, admite-se a substituição da pena privativa de liberdade por penas restritivas de direitos desde que o condenado não seja reincidente, que a pena a ele aplicada seja inferior a quatro anos e a culpabilidade, os antecedentes, a conduta social e a personalidade do condenado, bem como os motivos e as circunstâncias o autorizem.$q$,$q$Em se tratando do delito de lesão corporal culposa na direção de veículo automotor, ainda que praticado sob influência de álcool ou substância psicoativa, admite-se a substituição da pena privativa de liberdade por penas restritivas de direitos desde que o condenado não seja reincidente, que a pena a ele aplicada seja inferior a quatro anos e a culpabilidade, os antecedentes, a conduta social e a personalidade do condenado, bem como os motivos e as circunstâncias o autorizem.$q$,'X',1,'annulled',true,false,$q$Conforme o art. 312-B do Código Brasileiro de Trânsito, “Aos crimes previstos no § 3.º do art. 302 e no § 2.º do art. 303 deste Código não se aplica o disposto no inciso I do caput do art. 44 do Decreto-Lei n.º 2.848, de 7 de dezembro de 1940 (Código Penal)”.$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,68,$q$Direito Penal$q$,$q$A perda do cargo, da função ou do emprego público da pessoa condenada pelo crime de tortura é efeito automático da sentença condenatória.$q$,$q$A perda do cargo, da função ou do emprego público da pessoa condenada pelo crime de tortura é efeito automático da sentença condenatória.$q$,'C',1,'under_review',true,false,$q$Conforme dispõe o § 5.º do art. 1.º da Lei n.º 9.455/1997: “A condenação acarretará a perda do cargo, função ou emprego público e a interdição para seu exercício pelo dobro do prazo da pena aplicada.”$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,69,$q$Direito Penal$q$,$q$Caso o crime de feminicídio envolva violência doméstica e familiar, não há impedimento para a incidência simultânea da circunstância agravante genérica prevista para os crimes praticados com violência contra a mulher no âmbito das relações domésticas, pois a qualificadora pune a motivação de gênero, enquanto a agravante sanciona o prevalecimento da relação de confiança.$q$,$q$Caso o crime de feminicídio envolva violência doméstica e familiar, não há impedimento para a incidência simultânea da circunstância agravante genérica prevista para os crimes praticados com violência contra a mulher no âmbito das relações domésticas, pois a qualificadora pune a motivação de gênero, enquanto a agravante sanciona o prevalecimento da relação de confiança.$q$,'X',1,'annulled',true,false,$q$Se o crime praticado é o de feminicídio fundamentado na circunstância de envolver violência doméstica e familiar (Código Penal, art. 121-A, caput e § 1.º, I), não será cabível, na segunda fase da dosimetria em caso de condenação, a aplicação da agravante genérica prevista no art. 61, inciso II, alínea f (prevalecendo-se de relações domésticas ou com violência contra a mulher na forma da lei específica), uma vez que o contexto familiar e de violência contra a mulher já atua, neste cenário, como a própria elementar do delito.$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,70,$q$Direito Penal$q$,$q$Configura crime de falsificação de documento público a alteração material de testamento particular, de livros mercantis e dos títulos ao portador ou transmissíveis por endosso.$q$,$q$Configura crime de falsificação de documento público a alteração material de testamento particular, de livros mercantis e dos títulos ao portador ou transmissíveis por endosso.$q$,'C',1,'under_review',true,false,$q$Para fins penais, o testamento particular, os livros mercantis e os títulos ao portador ou transmissíveis por endosso se equiparam aos documentos públicos, conforme o § 2.º do art. 297 do Código Penal: “Para os efeitos penais, equiparam-se a documento público o emanado de entidade paraestatal, o título ao portador ou transmissível por endosso, as ações de sociedade comercial, os livros mercantis e o testamento particular.”$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,71,$q$Direito Tributário$q$,$q$O IBS, tributo de competência compartilhada entre estados e municípios inserido no ordenamento tributário brasileiro por meio da Reforma Tributária do Consumo, não alcança as prestações de serviço de comunicação nas modalidades de radiodifusão sonora e de sons e imagens de recepção livre e gratuita.$q$,$q$O IBS, tributo de competência compartilhada entre estados e municípios inserido no ordenamento tributário brasileiro por meio da Reforma Tributária do Consumo, não alcança as prestações de serviço de comunicação nas modalidades de radiodifusão sonora e de sons e imagens de recepção livre e gratuita.$q$,'C',1,'under_review',true,false,$q$Conforme previsto no art. 156-A, inciso XI, da Constituição Federal de 1988, o IBS “não incidirá nas prestações de serviço de comunicação nas modalidades de radiodifusão sonora e de sons e imagens de recepção livre e gratuita”.$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,72,$q$Direito Tributário$q$,$q$Diferentemente do ISS, o IBS incide sobre operações de locação de bens imóveis.$q$,$q$Diferentemente do ISS, o IBS incide sobre operações de locação de bens imóveis.$q$,'X',1,'annulled',true,false,$q$Em que pese a não incidência do ISS sobre a locação de bens imóveis, fruto do entendimento do STF – RE 403.036-AgR, rel. min. Celso de Mello. – o IBS, por expressa disposição constitucional, alcança essas operações: “Art. 156-A. Lei complementar instituirá imposto sobre bens e serviços de competência compartilhada entre Estados, Distrito Federal e Municípios. (...) § 6.º Lei complementar disporá sobre regimes específicos de tributação para: (...) II – serviços financeiros, operações com bens imóveis, planos de assistência à saúde e concursos de prognósticos, podendo prever” (...).$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,73,$q$Direito Tributário$q$,$q$A instauração de persecução penal, exceto a realizada em sede de investigação policial, relativa a crime que vise à redução de tributo por meio de declaração falsa às autoridades fazendárias somente se faz legítima após a definitiva constituição do crédito tributário.$q$,$q$A instauração de persecução penal, exceto a realizada em sede de investigação policial, relativa a crime que vise à redução de tributo por meio de declaração falsa às autoridades fazendárias somente se faz legítima após a definitiva constituição do crédito tributário.$q$,'E',1,'under_review',true,false,$q$Conforme entendimento do STF, a “instauração de persecução penal, desse modo, nos crimes contra a ordem tributária definidos no art. 1.º da Lei n.º 8.137/1990 somente se legitimará, mesmo em sede de investigação policial, após a definitiva constituição do crédito tributário, pois, antes que tal ocorra, o comportamento do agente será penalmente irrelevante, porque manifestamente atípico”. (vide Pet 3593QO). A conduta descrita no item está inserida no art. 1.º da Lei n.º 8137/1990: “Constitui crime contra a ordem tributária suprimir ou reduzir tributo, ou contribuição social e qualquer acessório, mediante as seguintes condutas: (Vide Lei n.º 9.964/2000) I - omitir informação, ou prestar declaração falsa às autoridades fazendárias.”$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,74,$q$Direito Tributário$q$,$q$No tocante aos crimes de apropriação indébita previdenciária, considerada a sua natureza formal, é prescindível o exaurimento do processo administrativo para efeito de encaminhamento da representação fiscal ao Ministério Público.$q$,$q$No tocante aos crimes de apropriação indébita previdenciária, considerada a sua natureza formal, é prescindível o exaurimento do processo administrativo para efeito de encaminhamento da representação fiscal ao Ministério Público.$q$,'E',1,'under_review',true,false,$q$Conforme entendimento do STF, formalizado por ocasião da ADI 4980, a “(...)exigência do exaurimento do processo administrativo para efeito de encaminhamento da representação fiscal ao Ministério Público é disciplina que, em vez de afrontar, privilegia os princípios da ordem constitucional brasileira e se mostra alinhada com a finalidade do direito penal enquanto ultima ratio. 6. O art. 83 da Lei n. 9.430/1996, com a redação da Lei n. 12.350/2010, apenas estabelece requisito, direcionado ao agente administrativo, quanto ao encaminhamento da representação fiscal para fins penais ao Ministério Público. Em nada modifica a natureza jurídica do crime de apropriação indébita previdenciária, tampouco trata da justa causa para os delitos contra a ordem tributária. 7. A validade da norma atacada independe da controvérsia relacionada à natureza dos delitos nela mencionados – se material ou formal –, notadamente o de apropriação indébita previdenciária (...)”.$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,75,$q$Direito Tributário$q$,$q$A conduta do contribuinte que deixa de recolher aos cofres públicos o ICMS cobrado do adquirente da mercadoria ou do serviço pode ser configurada como apropriação indébita tributária, uma vez demonstrados o caráter reiterado da conduta e o dolo específico.$q$,$q$A conduta do contribuinte que deixa de recolher aos cofres públicos o ICMS cobrado do adquirente da mercadoria ou do serviço pode ser configurada como apropriação indébita tributária, uma vez demonstrados o caráter reiterado da conduta e o dolo específico.$q$,'C',1,'under_review',true,false,$q$Conforme entendimento do STF, formalizado por ocasião do RHC 16334, o “contribuinte que deixa de recolher, de forma contumaz e com dolo de apropriação, o ICMS cobrado do adquirente da mercadoria ou serviço incide no tipo penal do art. 2.º, II, da Lei n.º 8.137/1990.”$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,76,$q$Direito Tributário$q$,$q$O compartilhamento de informações sigilosas bancárias pelas instituições financeiras em resposta à requisição do fisco é legítimo, desde que comprovada a existência de processo administrativo instaurado ou procedimento fiscal em curso.$q$,$q$O compartilhamento de informações sigilosas bancárias pelas instituições financeiras em resposta à requisição do fisco é legítimo, desde que comprovada a existência de processo administrativo instaurado ou procedimento fiscal em curso.$q$,'C',1,'under_review',true,false,$q$O STF, no julgamento do RE 601.314 (Tema 225-RG), assentou a constitucionalidade do art. 6.º da LC 105/2001, desde que observadas as condicionantes legais, notadamente a existência de processo administrativo instaurado ou procedimento fiscal em curso. Art. 6.º da LC 105/2001: “As autoridades e os agentes fiscais tributários da União, dos Estados, do Distrito Federal e dos Municípios somente poderão examinar documentos, livros e registros de instituições financeiras, inclusive os referentes a contas de depósitos e aplicações financeiras, quando houver processo administrativo instaurado ou procedimento fiscal em curso e tais exames sejam considerados indispensáveis pela autoridade administrativa competente.”$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,77,$q$Direito Tributário$q$,$q$A repetição do indébito tributário implica restituição, na mesma proporção, dos juros de mora e de todas as penalidades pecuniárias, incluídas as decorrentes de infrações de caráter formal.$q$,$q$A repetição do indébito tributário implica restituição, na mesma proporção, dos juros de mora e de todas as penalidades pecuniárias, incluídas as decorrentes de infrações de caráter formal.$q$,'E',1,'under_review',true,false,$q$Conforme previsto no art. 167 do CTN, a “restituição total ou parcial do tributo dá lugar à restituição, na mesma proporção, dos juros de mora e das penalidades pecuniárias, salvo as referentes a infrações de caráter formal não prejudicadas pela causa da restituição”.$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,78,$q$Direito Tributário$q$,$q$Lei complementar estadual pode disciplinar prazos de prescrição do crédito tributário para os tributos de competência do respectivo estado, ainda que não coincida com as regras estabelecidas no CTN.$q$,$q$Lei complementar estadual pode disciplinar prazos de prescrição do crédito tributário para os tributos de competência do respectivo estado, ainda que não coincida com as regras estabelecidas no CTN.$q$,'E',1,'under_review',true,false,$q$Exige-se lei complementar para dispor sobre prescrição e decadência tributárias aplicáveis às contribuições sociais (art. 146, inc. III, da Constituição) para constituição do crédito tributário e da respectiva ação de cobrança. Entendimento corroborado pela jurisprudência do STF –Tema n.º 3 de repercussão geral.$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,79,$q$Medicina Legal$q$,$q$Em vítima de morte violenta decorrente de ação da eletricidade natural (raio) em meio aberto, fenômeno conhecido como fulminação, o sinal de Lichtenberg corresponde a lesões cutâneas arboriformes.$q$,$q$Em vítima de morte violenta decorrente de ação da eletricidade natural (raio) em meio aberto, fenômeno conhecido como fulminação, o sinal de Lichtenberg corresponde a lesões cutâneas arboriformes.$q$,'C',1,'under_review',true,false,$q$A morte por ação de raios deixa o que a medicina legal chama de lesão patognomônica, lesão em forma de árvore, de nome Lichtenberg. FRANÇA, Genival Veloso. Medicina Legal. 12. ed. Rio de Janeiro: Guanabara Koogan, 2020, página 139.$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,80,$q$Medicina Legal$q$,$q$O parecer médico-legal é solicitado pelas partes ou pelo juiz para fins de análise e emissão de opinião técnica sobre perícia já realizada, diferenciando-se do relatório médico-legal principalmente por não conter a seção denominada descrição, que é a transcrição minuciosa do exame físico.$q$,$q$O parecer médico-legal é solicitado pelas partes ou pelo juiz para fins de análise e emissão de opinião técnica sobre perícia já realizada, diferenciando-se do relatório médico-legal principalmente por não conter a seção denominada descrição, que é a transcrição minuciosa do exame físico.$q$,'C',1,'under_review',true,false,$q$O parecer é uma peça de consulta. Como o perito do parecer não examina o corpo/objeto diretamente, mas sim os documentos periciais já existentes, o parecer não possui a "Descrição" (ou Visum et Repertum - ver e relatar) própria, passando direto para a discussão e conclusão. FRANÇA, Genival Veloso. Medicina Legal. 12. ed. Rio de Janeiro: Guanabara Koogan, 2020. cap. 2, p. 41.$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,81,$q$Medicina Legal$q$,$q$De acordo com a legislação penal brasileira vigente, o crime de estupro é configurado exclusivamente pela conjunção carnal, portanto qualquer outro ato libidinoso, ainda que praticado mediante violência ou grave ameaça, deve ser tipificado como crime de atentado violento ao pudor, exigindo-se laudos periciais distintos para cada conduta.$q$,$q$De acordo com a legislação penal brasileira vigente, o crime de estupro é configurado exclusivamente pela conjunção carnal, portanto qualquer outro ato libidinoso, ainda que praticado mediante violência ou grave ameaça, deve ser tipificado como crime de atentado violento ao pudor, exigindo-se laudos periciais distintos para cada conduta.$q$,'E',1,'under_review',true,false,$q$Desde a alteração trazida pela Lei n.º 12.015/2009, o crime de atentado violento ao pudor foi absorvido pelo tipo penal de estupro (Código Penal, art. 213). Atualmente, o estupro é definido como “constranger alguém, mediante violência ou grave ameaça, a ter conjunção carnal ou a praticar ou permitir que com ele se pratique outro ato libidinoso”. Portanto, ambos estão unificados no mesmo artigo.$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,82,$q$Medicina Legal$q$,$q$A conjunção carnal, para fins de tipificação do crime de estupro, é caracterizada juridicamente pela penetração, ainda que parcial, do pênis na cavidade vaginal, ocorrendo ou não ejaculação ou a ruptura do hímen.$q$,$q$A conjunção carnal, para fins de tipificação do crime de estupro, é caracterizada juridicamente pela penetração, ainda que parcial, do pênis na cavidade vaginal, ocorrendo ou não ejaculação ou a ruptura do hímen.$q$,'C',1,'under_review',true,false,$q$Segundo a literatura de referência na área da medicina legal, entende-se como conjunção carnal a introdução completa ou incompleta do pênis na cavidade vaginal, ocorrendo ou não ejaculação, não se tendo como tal a cópula vestibular ou vulvar nem o coito oral ou anal. FRANÇA, Genival Veloso. Medicina Legal. 12. ed. Rio de Janeiro: Guanabara Koogan, 2020. cap. 8, p. 278.$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,83,$q$Medicina Legal$q$,$q$Considere que uma mulher adulta compareça ao Instituto Médico Legal e relate ter sido vítima de agressão sexual recente; considere, ainda, que, durante exame físico minucioso, o perito médico-legista observe a presença de equimoses digitais nas faces internas das coxas da mulher e hiperemia na região anal, acompanhada de pequenas fissuras radiadas sangrantes, caracterizadas como recentes, e o exame ginecológico revele hímen íntegro, do tipo anular, sem sinais de ruptura ou entalhes, e ausência de espermatozoides no conteúdo vaginal. Nessa situação hipotética, a integridade himenal e a ausência de espermatozoides na cavidade vaginal da vítima não impedem a tipificação do crime de estupro, uma vez que os vestígios encontrados caracterizam ato libidinoso praticado de forma violenta.$q$,$q$Considere que uma mulher adulta compareça ao Instituto Médico Legal e relate ter sido vítima de agressão sexual recente; considere, ainda, que, durante exame físico minucioso, o perito médico-legista observe a presença de equimoses digitais nas faces internas das coxas da mulher e hiperemia na região anal, acompanhada de pequenas fissuras radiadas sangrantes, caracterizadas como recentes, e o exame ginecológico revele hímen íntegro, do tipo anular, sem sinais de ruptura ou entalhes, e ausência de espermatozoides no conteúdo vaginal. Nessa situação hipotética, a integridade himenal e a ausência de espermatozoides na cavidade vaginal da vítima não impedem a tipificação do crime de estupro, uma vez que os vestígios encontrados caracterizam ato libidinoso praticado de forma violenta.$q$,'C',1,'under_review',true,false,$q$Conforme a legislação atual, tanto o homem quanto a mulher poderão ser sujeito ativo ou passivo do crime de estupro, pois admite-se que qualquer ato libidinoso praticado de forma violenta ou de grave ameaça a alguém é tido como o delito em questão. FRANÇA, Genival Veloso. Medicina Legal. 12. ed. Rio de Janeiro: Guanabara Koogan, 2020. cap. 8, p. 286.$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,84,$q$Medicina Legal$q$,$q$Suponha que um caso de estupro ocorrido há dois anos seja reaberto após a identificação de um suspeito pela vítima; suponha, ainda, que da agressão tenha resultado uma gestação e o nascimento de uma criança, hoje com 1 ano e 3 meses de idade; por fim, suponha que, à época do crime, não tenham sido coletados vestígios biológicos do agressor (esperma ou células epiteliais). Nessa situação hipotética, o exame de DNA realizado entre o suspeito e o filho da vítima pode ser utilizado como prova fundamental para a elucidação da autoria do crime, possuindo valor probatório robusto para a condenação, desde que confirmada a paternidade.$q$,$q$Suponha que um caso de estupro ocorrido há dois anos seja reaberto após a identificação de um suspeito pela vítima; suponha, ainda, que da agressão tenha resultado uma gestação e o nascimento de uma criança, hoje com 1 ano e 3 meses de idade; por fim, suponha que, à época do crime, não tenham sido coletados vestígios biológicos do agressor (esperma ou células epiteliais). Nessa situação hipotética, o exame de DNA realizado entre o suspeito e o filho da vítima pode ser utilizado como prova fundamental para a elucidação da autoria do crime, possuindo valor probatório robusto para a condenação, desde que confirmada a paternidade.$q$,'C',1,'under_review',true,false,$q$De acordo com a literatura de referência na área da medicina legal, a presença de gravidez de idade compatível com um alegado estupro tem uma importância muito grande, levando-se em conta ainda os meios hemogenéticos de vinculação de filiação, principalmente pelo DNA. FRANÇA, Genival Veloso. Medicina Legal. 12. ed. Rio de Janeiro: Guanabara Koogan, 2020. cap. 8, p. 286.$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,85,$q$Medicina Legal$q$,$q$Considere que uma mulher mate, sob a influência do estado puerperal, o próprio filho logo após o parto. Nesse caso, a conduta é tipificada como infanticídio, crime de homicídio, sendo a pena prevista reduzida com base no critério biopsicossocial.$q$,$q$Considere que uma mulher mate, sob a influência do estado puerperal, o próprio filho logo após o parto. Nesse caso, a conduta é tipificada como infanticídio, crime de homicídio, sendo a pena prevista reduzida com base no critério biopsicossocial.$q$,'E',1,'under_review',true,false,$q$A legislação vigente adota como atenuante do crime de infanticídio a condição biopsicossocial do estado puerperal, justificado pelo trauma psicológico. O infanticídio é qualificado como delictum exceptum quando praticado pela parturiente sob a influência do estado puerperal. FRANÇA, Genival Veloso. Medicina Legal. 12. ed. Rio de Janeiro: Guanabara Koogan, 2020. cap. 13, p. 359.$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. ATENÇÃO: a resposta do gabarito preliminar com justificativas (item 85) foi 'C', divergente da resposta do gabarito oficial definitivo ('E') — provável alteração por recurso; justificativa abaixo reflete o raciocínio do gabarito PRELIMINAR e pode não corresponder à fundamentação da resposta definitiva. Necessária revisão jurídica específica antes de content_status=active. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,86,$q$Medicina Legal$q$,$q$Suponha que uma mulher adulta seja encaminhada à perícia por autoridade policial devido à denúncia de que teria ingerido, em clínica de aborto, substâncias químicas e sido submetida à introdução de objetos no canal vaginal para a interrupção de gestação de aproximadamente 10 semanas; suponha, ainda, que, ao exame físico, o perito médico-legista observe a presença de pequenas escoriações e equimoses no colo uterino entreaberto, com presença de sangue fluido e grumos, além de resquícios de pó branco não identificado em fundo de saco vaginal, bem como ausência de feto ou restos ovulares visíveis. Nessa situação hipotética, para a confirmação da materialidade do crime de aborto provocado, o perito poderia dispensar a realização do exame anatomopatológico caso o teste de gravidez (Beta-hCG) resultasse positivo, uma vez que a presença do hormônio é prova absoluta de que a interrupção foi provocada por meios mecânicos conforme sugerem as lesões no colo do útero.$q$,$q$Suponha que uma mulher adulta seja encaminhada à perícia por autoridade policial devido à denúncia de que teria ingerido, em clínica de aborto, substâncias químicas e sido submetida à introdução de objetos no canal vaginal para a interrupção de gestação de aproximadamente 10 semanas; suponha, ainda, que, ao exame físico, o perito médico-legista observe a presença de pequenas escoriações e equimoses no colo uterino entreaberto, com presença de sangue fluido e grumos, além de resquícios de pó branco não identificado em fundo de saco vaginal, bem como ausência de feto ou restos ovulares visíveis. Nessa situação hipotética, para a confirmação da materialidade do crime de aborto provocado, o perito poderia dispensar a realização do exame anatomopatológico caso o teste de gravidez (Beta-hCG) resultasse positivo, uma vez que a presença do hormônio é prova absoluta de que a interrupção foi provocada por meios mecânicos conforme sugerem as lesões no colo do útero.$q$,'E',1,'under_review',true,false,$q$O resultado positivo do exame de Beta- hCG confirma que a mulher está ou esteve grávida recentemente, mas ele não prova que a interrupção foi provocada. O hormônio permanece detectável no organismo por algum tempo mesmo após um aborto espontâneo. De acordo com a literatura de referência na área da medicina legal, o exame anatomopatológico dos restos ovulares (se encontrados) ou da curetagem é considerado padrão- ouro, em perícia de aborto. Ele busca identificar vilosidades coriônicas ou decíduas, confirmando a gravidez. As lesões no colo uterino sugerem o uso de meios mecânicos, mas a materialidade exige a tríade diagnóstica: prova da gravidez preexistente, prova da expulsão do produto e, crucialmente, a prova do meio empregado. FRANÇA, Genival Veloso. Medicina Legal. 12. ed. Rio de Janeiro: Guanabara Koogan, 2020. cap. 9 \[Obstetrícia Forense: Aborto\], p. 280-295.$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,87,$q$Direito Processual Penal$q$,$q$O afastamento da prova pericial pelo magistrado não enseja, por si só, nulidade processual, desde que a decisão esteja fundamentada na apreciação global da prova, ainda que de forma implícita e parcial.$q$,$q$O afastamento da prova pericial pelo magistrado não enseja, por si só, nulidade processual, desde que a decisão esteja fundamentada na apreciação global da prova, ainda que de forma implícita e parcial.$q$,'E',1,'under_review',true,false,$q$O princípio do livre convencimento motivado ou da persuasão racional, previsto no art. 155 do CPP, não autoriza valoração arbitrária da prova. O magistrado pode afastar a prova pericial que não possui validade absoluta, mas deve fazê-lo mediante fundamentação idônea e explícita, sob pena de nulidade por violação ao dever constitucional de motivação das decisões judiciais. Ao mesmo tempo, o afastamento do laudo pericial, documento de natureza eminentemente técnica, deve ser especificamente motivado, com a indicação concreta das razões técnicas e probatórias que infirmem as suas conclusões. O artigo 93, IX, da Constituição Federal de 1988, estabelece a obrigatoriedade de fundamentação de todas as decisões judiciais, sob pena de nulidade. A jurisprudência do STJ é firme no sentido de que a prova técnica não pode ser desconsiderada sem fundamentação técnica concreta, sobretudo quando se tratar de elemento central da controvérsia. CPP: Art. 155. O juiz formará sua convicção pela livre apreciação da prova produzida em contraditório judicial, não podendo fundamentar sua decisão exclusivamente nos elementos informativos colhidos na investigação, ressalvadas as provas cautelares, não repetíveis e antecipadas. Parágrafo único. Somente quanto ao estado das pessoas serão observadas as restrições estabelecidas na lei civil.$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,88,$q$Direito Processual Penal$q$,$q$A prova ilícita por derivação poderá ser admitida no processo penal quando demonstrado que a prova subsequente seria inevitavelmente descoberta por fonte independente, hipótese que afasta a incidência da teoria dos frutos da árvore envenenada.$q$,$q$A prova ilícita por derivação poderá ser admitida no processo penal quando demonstrado que a prova subsequente seria inevitavelmente descoberta por fonte independente, hipótese que afasta a incidência da teoria dos frutos da árvore envenenada.$q$,'C',1,'under_review',true,false,$q$Segundo o art. 157, § 1.º, do CPP, “são inadmissíveis, devendo ser desentranhadas do processo, as provas ilícitas, assim entendidas as obtidas em violação a normas constitucionais ou legais”, sendo também “inadmissíveis as provas derivadas das ilícitas, salvo quando não evidenciado o nexo de causalidade entre umas e outras, ou quando as derivadas puderem ser obtidas por uma fonte independente das primeiras.” O § 2.º do mesmo dispositivo legal considera fonte independente aquela que, por si só, seguindo os trâmites típicos e de praxe próprios da investigação ou instrução criminal, seria capaz de conduzir ao fato objeto da prova. Em situação tal, afasta-se a incidência da teoria dos frutos da árvore envenenada. Trata-se de exceção expressa de aceitação da prova ilícita por derivação, quando esta não é contaminada de ilicitude, na hipótese de que o elemento probatório seria inevitavelmente descoberto por fonte independente. O STF e o STJ adotam a teoria dos frutos da árvore envenenada, entendendo que a prova ilícita contamina, em regra, os elementos dela derivados. Contudo, ambas as cortes admitem as exceções da fonte independente e da descoberta inevitável, desde que ausente nexo causal com a ilicitude originária ou demonstrado que a prova seria produzida de qualquer modo por atividades lícitas e ordinárias de investigação. No STF, esse entendimento aparece em precedentes que reconhecem o desentranhamento da prova ilícita e a preservação apenas de elementos autônomos. No STJ, é firme o entendimento de que a ilicitude por reverberação alcança as provas derivadas, salvo nas hipóteses legais do art. 157, §§ 1.º e 2.º, do CPP.$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,89,$q$Direito Processual Penal$q$,$q$A licitude da busca domiciliar no período noturno sem mandado judicial prescinde da demonstração de situação de flagrante delito ou de desastre caso haja consentimento válido, livre e esclarecido do morador, sendo a validade desse consentimento condicionada à possibilidade de posterior controle judicial do ato, conforme a jurisprudência dos tribunais superiores.$q$,$q$A licitude da busca domiciliar no período noturno sem mandado judicial prescinde da demonstração de situação de flagrante delito ou de desastre caso haja consentimento válido, livre e esclarecido do morador, sendo a validade desse consentimento condicionada à possibilidade de posterior controle judicial do ato, conforme a jurisprudência dos tribunais superiores.$q$,'C',1,'under_review',true,false,$q$A busca domiciliar noturna sem mandado judicial é lícita quando houver consentimento válido, livre e esclarecido do morador, não sendo necessária, nessa hipótese, a demonstração de flagrante delito, desastre ou prestação de socorro. O STF e o STJ exigem, contudo, que o consentimento seja inequívoco, preferencialmente documentado e passível de controle judicial posterior. No STF, o Tema n.º 280 fixa que a entrada forçada em domicílio, inclusive no período noturno, só é lícita quando amparada em fundadas razões, devidamente justificadas a posteriori, que indiquem situação de flagrante delito. Mais recentemente, a corte reafirmou que, quando o ingresso policial se sustenta no consentimento do morador, a validade da diligência depende da existência de autorização livre e do controle posterior das circunstâncias do caso. No STJ, a orientação é ainda mais rigorosa no controle do consentimento: a prova da autorização para ingresso no domicílio deve ser inequívoca, livre e, preferencialmente, documentada, com registro escrito, testemunhas ou áudio/vídeo, sob pena de nulidade da prova e das derivadas. Em síntese, o STF e o STJ admitem o consentimento como hipótese legitimadora, mas exigem demonstração segura da voluntariedade e rejeitam consentimento presumido ou obtido sob pressão.$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,90,$q$Direito Processual Penal$q$,$q$O reconhecimento de pessoas por fotografia, na fase inquisitiva, ainda que realizado em desconformidade com o procedimento previsto no Código de Processo Penal, poderá ser valorado como elemento probatório idôneo se confirmado em juízo sob o crivo do contraditório.$q$,$q$O reconhecimento de pessoas por fotografia, na fase inquisitiva, ainda que realizado em desconformidade com o procedimento previsto no Código de Processo Penal, poderá ser valorado como elemento probatório idôneo se confirmado em juízo sob o crivo do contraditório.$q$,'E',1,'under_review',true,false,$q$A Sexta Turma do STJ, nos autos do HC 598.886/SC, de relatoria do ministro Rogério Schietti Cruz, em julgamento realizado em 27/10/2020, conferiu nova interpretação ao art. 226 do CPP, ao firmar o entendimento de que o reconhecimento de pessoa realizado na fase inquisitiva, presencialmente ou por fotografia, somente está apto para a identificação do réu e fixação da autoria delitiva quando observadas as formalidades descritas na citada norma processual e quando corroborado por outras provas colhidas na fase judicial, sob o crivo do contraditório e da ampla defesa. “Na espécie, não há que se falar nulidade dos reconhecimentos pessoais, tendo em vista que os referidos meios de prova estão aptos para a identificação dos acusados e para a fixação da autoria delitiva (devida observância às regras probatórias previstas no art. 226 do CPP), além de estarem corroborados por outros elementos probatórios.” (Acórdão 1438219, 07118847220218070003, relator: Robson Barbosa de Azevedo, Segunda Turma Criminal, data de julgamento: 14/7/2022, publicado no DJe: 28/7/2022). Reconhecimento de pessoa suspeita – formalidades previstas no art. 226 do CPP – garantia da viabilidade do reconhecimento como prova “1. O reconhecimento de pessoas, presencial ou por fotografia, deve observar o procedimento previsto no art. 226 do Código de Processo Penal, cujas formalidades constituem garantia mínima para quem se encontra na condição de suspeito da prática de um crime e para uma verificação dos fatos mais justa e precisa. 2. A inobservância do procedimento descrito na referida norma processual torna inválido o reconhecimento da pessoa suspeita, de modo que tal elemento não poderá fundamentar eventual condenação ou decretação de prisão cautelar, mesmo se refeito e confirmado o reconhecimento em Juízo. Se declarada a irregularidade do ato, eventual condenação já proferida poderá ser mantida, se fundamentada em provas independentes e não contaminadas.” (RHC 206.846/SP, relator: ministro Gilmar Mendes, Segunda Turma, data de julgamento: 22/2/2022, publicado em 25/5/2022)$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,91,$q$Direito Processual Penal$q$,$q$A oitiva de testemunha realizada sem o compromisso legal de dizer a verdade é nula de pleno direito, sendo vedada qualquer valoração de suas declarações pelo magistrado, inclusive como elemento de corroboração de outras provas produzidas sob o crivo do contraditório.$q$,$q$A oitiva de testemunha realizada sem o compromisso legal de dizer a verdade é nula de pleno direito, sendo vedada qualquer valoração de suas declarações pelo magistrado, inclusive como elemento de corroboração de outras provas produzidas sob o crivo do contraditório.$q$,'X',1,'annulled',true,false,$q$Nos termos dos arts. 202, 203 e 206 do CPP, é certo que toda pessoa pode ser testemunha e que, em regra, a testemunha presta compromisso de dizer a verdade. Ocorre, contudo, que essa regra não é absoluta. A própria legislação processual admite hipóteses em que o depoente é ouvido sem compromisso, na condição de informante, especialmente quando presente impedimento, suspeição ou vínculo de parentesco que recomenda tratamento processual diferenciado, caso em que o valor probatório de suas declarações será apreciado pelo magistrado com a devida cautela. A jurisprudência do STJ e do STF é firme no sentido de que nem toda pessoa ouvida em juízo está sujeita ao compromisso legal de dizer a verdade. Parentes próximos, pessoas impedidas ou suspeitas e outros depoentes legalmente excepcionados podem ser inquiridos como informantes, sem o juramento típico da testemunha compromissada. Nessas hipóteses, o depoimento é válido e pode ser valorado pelo juízo, mas não se confunde com a prova testemunhal estrita, devendo ser examinado à luz das circunstâncias do caso concreto e do grau de credibilidade que inspirar. Nesse contexto, não é nula, de pleno direito, a oitiva de testemunha realizada sem o compromisso legal de dizer a verdade, ainda que se trate de informante.$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,92,$q$Legislação Especial (Violência Doméstica e Familiar)$q$,$q$A concessão de medidas protetivas de urgência, no âmbito de inquérito policial para a apuração de violência doméstica contra mulher, está condicionada à demonstração inequívoca da autoria e, especialmente, à comprovação da materialidade delitiva, inclusive nas hipóteses de violência psicológica.$q$,$q$A concessão de medidas protetivas de urgência, no âmbito de inquérito policial para a apuração de violência doméstica contra mulher, está condicionada à demonstração inequívoca da autoria e, especialmente, à comprovação da materialidade delitiva, inclusive nas hipóteses de violência psicológica.$q$,'E',1,'under_review',true,false,$q$A concessão de medidas protetivas de urgência não exige prova plena da materialidade, bastando indícios de autoria e situação de risco, inclusive com base na palavra da vítima e em elementos informativos colhidos no inquérito. Considerando os termos da Lei n.º 11.340/2006, em seu art. 19, §§ 5.º e 6.º, o STJ, no Tema n.º 1.249 (AgRg no HC 822834-MG), pacificou o entendimento de que as medidas protetivas de urgência serão concedidas independentemente de tipificação penal, ajuizamento de ação penal e “da existência de inquérito policial ou do registro de boletim de ocorrência”, e vigorarão enquanto persistir risco. Além da natureza preventiva, o STJ enfatiza que a decisão sobre manter ou revogar medidas deve considerar se os elementos já analisados indicam risco e se a situação de vulnerabilidade persiste. Assim, não se exige “prova plena” para sustentar a cautela; o que se exige é sua justificação baseada em elementos suficientes e verossímeis, com o devido contraditório quando pertinente à revogação.$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,93,$q$Legislação Especial (Violência Doméstica e Familiar)$q$,$q$A revogação ou modificação das medidas protetivas de urgência concedidas à mulher em contexto de violência doméstica e familiar somente poderá ocorrer por decisão judicial fundamentada, sendo vedado ao delegado de polícia, mesmo diante de fatos supervenientes apurados no inquérito policial, promover a cessação de seus efeitos, ainda que haja concordância expressa da vítima.$q$,$q$A revogação ou modificação das medidas protetivas de urgência concedidas à mulher em contexto de violência doméstica e familiar somente poderá ocorrer por decisão judicial fundamentada, sendo vedado ao delegado de polícia, mesmo diante de fatos supervenientes apurados no inquérito policial, promover a cessação de seus efeitos, ainda que haja concordância expressa da vítima.$q$,'C',1,'under_review',true,false,$q$As medidas protetivas têm natureza jurisdicional, razão pela qual somente o juiz pode revogá-las ou modificá-las, mediante decisão fundamentada. O delegado de polícia, mesmo diante de fatos supervenientes apurados no inquérito, não detém competência para cessar seus efeitos, sendo irrelevante a concordância da vítima. Prevalece o princípio da reserva de jurisdição. Conforme o Ar. 19 da Lei 11.340/06, “as medidas protetivas de urgência poderão ser concedidas pelo juiz, a requerimento do Ministério Público ou a pedido da ofendida.” O §5º, do dispositivo citado, acrescenta que “as medidas protetivas de urgência vigorarão enquanto persistir situação de risco para a ofendida, “independentemente da tipificação penal da violência, do ajuizamento de ação penal ou cível, da existência de inquérito policial, ou do registro de boletim de ocorrência.” Nesse contexto, as medidas protetivas de urgência no âmbito da Lei Maria da Penha, têm natureza autônoma, o que vem também positivado no Tema 1249/STJ. Verifica-se desse contexto citado, que o delegado de polícia não dispõe de legitimidade para requerer a MPU, tampouco rever, modificar ou fazer cessar os seus termos, ainda que haja concordância expressa da ofendida.$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,94,$q$Legislação Especial (Violência Doméstica e Familiar)$q$,$q$O descumprimento de medida protetiva de urgência concedida a mulher vítima de violência doméstica configura crime autônomo, de ação penal pública incondicionada, cuja apuração independe do prosseguimento do inquérito policial instaurado para a investigação do delito de violência doméstica que deu origem à concessão da medida.$q$,$q$O descumprimento de medida protetiva de urgência concedida a mulher vítima de violência doméstica configura crime autônomo, de ação penal pública incondicionada, cuja apuração independe do prosseguimento do inquérito policial instaurado para a investigação do delito de violência doméstica que deu origem à concessão da medida.$q$,'C',1,'under_review',true,false,$q$O art. 24-A da Lei n.º 11.340/2006 tipifica o descumprimento de medida protetiva de urgência como crime autônomo, de ação penal pública incondicionada. Sua apuração independe do desfecho do inquérito policial relativo ao delito originário, sendo possível, inclusive, a lavratura de auto de prisão em flagrante exclusivamente pelo descumprimento da medida judicial. Ora, se a própria medida protetiva tem natureza autônoma, nos termos do § 5º, do Art. 19 da mencionada Lei, o seu descumprimento, por todo o óbvio, também independe de conclusão do procedimento policial instaurado para a investigação do delito que originou a cautelar protetiva.$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,95,$q$Legislação Especial (Violência Doméstica e Familiar)$q$,$q$Quando existente risco atual ou iminente à vida ou à integridade física de criança ou adolescente vítima de violência doméstica e familiar, o delegado de polícia poderá promover o afastamento imediato do agressor do lar, domicílio ou local de convivência com a vítima, caso o município não seja sede de comarca, devendo comunicar o juízo no prazo de 24 horas.$q$,$q$Quando existente risco atual ou iminente à vida ou à integridade física de criança ou adolescente vítima de violência doméstica e familiar, o delegado de polícia poderá promover o afastamento imediato do agressor do lar, domicílio ou local de convivência com a vítima, caso o município não seja sede de comarca, devendo comunicar o juízo no prazo de 24 horas.$q$,'C',1,'under_review',true,false,$q$O art. 14, II, § 2.º, da Lei n.º 14.344/2022 permite que o delegado de polícia promova o afastamento do agressor do lar ou do local de convivência com a vítima, nos casos de risco atual ou iminente à vida ou à integridade física da criança ou do adolescente, devendo comunicar o juízo no prazo de 24 horas.$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,96,$q$Legislação Especial (Violência Doméstica e Familiar)$q$,$q$No curso de inquérito policial instaurado com fundamento na Lei Henry Borel, a concessão de medidas protetivas de urgência em favor da criança ou do adolescente está condicionada à prévia oitiva do investigado e à manifestação do Ministério Público, sob pena de violação do contraditório e da ampla defesa.$q$,$q$No curso de inquérito policial instaurado com fundamento na Lei Henry Borel, a concessão de medidas protetivas de urgência em favor da criança ou do adolescente está condicionada à prévia oitiva do investigado e à manifestação do Ministério Público, sob pena de violação do contraditório e da ampla defesa.$q$,'E',1,'under_review',true,false,$q$As medidas protetivas de urgência previstas na Lei Henry Borel têm natureza cautelar e eminentemente protetiva, podendo ser concedidas inaudita altera pars, especialmente quando presentes indícios de risco atual ou iminente à integridade física ou psicológica da criança ou do adolescente (art. 16 da Lei n.º 14.344/2022). Não se exigem a prévia oitiva do investigado nem manifestação antecedente do Ministério Público para o deferimento inicial das medidas, sendo plenamente admitido o contraditório diferido. O STJ afirma que a tutela é inibitória e não depende de prova exauriente, bastando elementos concretos de verossimilhança e perigo, com possibilidade de contraditório diferido. Em reforço, o STF prestigia a lógica cautelar quando a medida se mostra necessária para resguardar a vítima, afastando exigência de cognição plena incompatível com a urgência. Em síntese, conforme o entendimento dos tribunais superiores, o deferimento inicial das medidas protetivas da Lei Henry Borel prescinde de oitiva prévia do investigado e pode se apoiar em quadro indiciário suficiente, desde que a decisão esteja fundamentada na urgência e no risco concreto. (vide STF - Acórdão SJUR 523441-HC 249130 AgR, rel. ministro André Mendonça, 23/2/2025)$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,97,$q$Legislação Especial (Violência Doméstica e Familiar)$q$,$q$A Lei Maria da Penha veda a aplicação, nos casos de violência doméstica e familiar contra a mulher, tanto de penas de cesta básica ou outras de prestação pecuniária quanto a substituição de pena que implique o pagamento isolado de multa.$q$,$q$A Lei Maria da Penha veda a aplicação, nos casos de violência doméstica e familiar contra a mulher, tanto de penas de cesta básica ou outras de prestação pecuniária quanto a substituição de pena que implique o pagamento isolado de multa.$q$,'C',1,'under_review',true,false,$q$Lei n.º 11.340/2006: “Art. 17. É vedada a aplicação, nos casos de violência doméstica e familiar contra a mulher, de penas de cesta básica ou outras de prestação pecuniária, bem como a substituição de pena que implique o pagamento isolado de multa.”$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,98,$q$Legislação Especial (Organizações Criminosas, Lavagem de Dinheiro e Drogas)$q$,$q$A Lei de Combate às Organizações Criminosas autoriza que a formalização de colaboração premiada seja realizada somente após o oferecimento da denúncia, vedando a sua celebração no curso do inquérito policial em razão da ausência de contraditório e de controle jurisdicional neste momento.$q$,$q$A Lei de Combate às Organizações Criminosas autoriza que a formalização de colaboração premiada seja realizada somente após o oferecimento da denúncia, vedando a sua celebração no curso do inquérito policial em razão da ausência de contraditório e de controle jurisdicional neste momento.$q$,'E',1,'under_review',true,false,$q$A colaboração premiada pode ser celebrada em qualquer fase da persecução penal, inclusive durante o inquérito policial, nos termos do artigo 3.º da Lei n.º 12.850/2013. Nessa hipótese, o acordo é formalizado com a participação da autoridade policial e depende de homologação judicial, oportunidade em que se exerce o controle de legalidade, sendo desnecessário o prévio oferecimento da denúncia.$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,99,$q$Legislação Especial (Organizações Criminosas, Lavagem de Dinheiro e Drogas)$q$,$q$É dispensável a comprovação prévia do crime antecedente para a instauração de inquérito policial e para o indiciamento pela prática do crime de lavagem de dinheiro, sendo igualmente admissível, nessa fase, a adoção de medidas de rastreamento e de constrição patrimonial, nos termos da legislação vigente.$q$,$q$É dispensável a comprovação prévia do crime antecedente para a instauração de inquérito policial e para o indiciamento pela prática do crime de lavagem de dinheiro, sendo igualmente admissível, nessa fase, a adoção de medidas de rastreamento e de constrição patrimonial, nos termos da legislação vigente.$q$,'C',1,'under_review',true,false,$q$A Lei n.º 9.613/1998 consagra a autonomia do delito de lavagem de dinheiro em relação ao crime antecedente. Nos termos do art. 2.º, § 1.º, dessa lei, a persecução penal do crime de lavagem de dinheiro independe da apuração, do processamento ou da condenação pelo crime antecedente, o que afasta a exigência de sua comprovação prévia para a instauração de inquérito policial ou para o indiciamento. Além disso, o art. 4.º da mesma lei autoriza a adoção de medidas assecuratórias de bens, direitos ou valores relacionados à infração, inclusive na fase investigativa, com a finalidade de assegurar o ressarcimento do dano e a eficácia da persecução penal, sendo tais medidas compatíveis com a atuação da autoridade policial, mediante representação ao juízo competente. Assim, à luz dos dispositivos legais mencionados, é legalmente válida a instauração de investigação, o indiciamento e a promoção de medidas de rastreamento e constrição patrimonial no crime de lavagem de dinheiro, ainda que ausente a comprovação prévia do crime antecedente.$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,100,$q$Legislação Especial (Organizações Criminosas, Lavagem de Dinheiro e Drogas)$q$,$q$Em qualquer fase da persecução penal dos crimes previstos na Lei Antidrogas, admite-se, mediante autorização judicial e prévia oitiva do Ministério Público, a não atuação policial imediata sobre portadores de drogas ilícitas ou de insumos destinados à sua produção, com o objetivo de identificar e responsabilizar maior número de integrantes da cadeia criminosa, sem óbice à futura responsabilização penal dos envolvidos.$q$,$q$Em qualquer fase da persecução penal dos crimes previstos na Lei Antidrogas, admite-se, mediante autorização judicial e prévia oitiva do Ministério Público, a não atuação policial imediata sobre portadores de drogas ilícitas ou de insumos destinados à sua produção, com o objetivo de identificar e responsabilizar maior número de integrantes da cadeia criminosa, sem óbice à futura responsabilização penal dos envolvidos.$q$,'C',1,'under_review',true,false,$q$O art. 53, II, da Lei n.º 11.343/2006 disciplina que “em qualquer fase da persecução criminal relativa aos crimes previstos nesta Lei, são permitidos, além dos previstos em lei, mediante autorização judicial e ouvido o Ministério Público, os seguintes procedimentos investigatórios: I - a infiltração por agentes de polícia, em tarefas de investigação, constituída pelos órgãos especializados pertinentes; II - a não atuação policial sobre os portadores de drogas, seus precursores químicos ou outros produtos utilizados em sua produção, que se encontrem no território brasileiro, com a finalidade de identificar e responsabilizar maior número de integrantes de operações de tráfico e distribuição, sem prejuízo da ação penal cabível.”.$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,101,$q$Direito Processual Penal$q$,$q$Nos casos de infração insuscetível de fiança, ainda que se trate de delito hediondo ou equiparado, a vedação legal à fiança, por si só, não implica a inadmissibilidade de liberdade provisória, sendo irrelevante a mera hediondez da conduta para a segregação cautelar.$q$,$q$Nos casos de infração insuscetível de fiança, ainda que se trate de delito hediondo ou equiparado, a vedação legal à fiança, por si só, não implica a inadmissibilidade de liberdade provisória, sendo irrelevante a mera hediondez da conduta para a segregação cautelar.$q$,'C',1,'under_review',true,false,$q$A liberdade provisória constitui regra, ao passo que a prisão cautelar é exceção. Ausentes os pressupostos da prisão preventiva, deve o juiz conceder liberdade provisória, ainda que se trate de crime hediondo, podendo impor medidas cautelares, caso se trate de crime inafiançável, em respeito ao princípio da proporcionalidade.$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,102,$q$Direito Processual Penal$q$,$q$Suponha que, no curso de uma investigação acerca de suposta organização criminosa, a autoridade policial tenha submetido ao juízo competente representação que visa decretar a prisão temporária do grupo investigado. Nesse caso, o juiz pode decretar a prisão cautelar sem a prévia manifestação ministerial, sob o fundamento da necessidade da custódia cautelar e da garantia da eficácia investigativa.$q$,$q$Suponha que, no curso de uma investigação acerca de suposta organização criminosa, a autoridade policial tenha submetido ao juízo competente representação que visa decretar a prisão temporária do grupo investigado. Nesse caso, o juiz pode decretar a prisão cautelar sem a prévia manifestação ministerial, sob o fundamento da necessidade da custódia cautelar e da garantia da eficácia investigativa.$q$,'E',1,'under_review',true,false,$q$De acordo com o art. 2.º da Lei n.º 7.960/1989, “a prisão temporária será decretada pelo Juiz, em face da representação da autoridade policial ou de requerimento do Ministério Público, e terá o prazo de 5 (cinco) dias, prorrogável por igual período em caso de extrema e comprovada necessidade.” Na sequência, o parágrafo primeiro do mesmo dispositivo legal assevera que “na hipótese de representação da autoridade policial, o Juiz, antes de decidir, ouvirá o Ministério Público.”. Assim, a prévia oitiva do Ministério Público, nos casos em que o delegado de polícia representa pela prisão temporária, é de obrigatória observação pelo magistrado, como garantia para resguardar a legalidade da medida durante a fase de investigação.$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,103,$q$Direito Processual Penal$q$,$q$Após a lavratura do auto de prisão em flagrante por infração penal cuja pena privativa de liberdade máxima cominada não exceda quatro anos, compete, em regra, à autoridade policial conceder fiança, independentemente de prévia manifestação judicial, desde que atendidos os requisitos legais para a sua concessão.$q$,$q$Após a lavratura do auto de prisão em flagrante por infração penal cuja pena privativa de liberdade máxima cominada não exceda quatro anos, compete, em regra, à autoridade policial conceder fiança, independentemente de prévia manifestação judicial, desde que atendidos os requisitos legais para a sua concessão.$q$,'C',1,'under_review',true,false,$q$O CPP autoriza expressamente a concessão de fiança pela autoridade policial nos casos de infração penal cuja pena privativa de liberdade máxima não seja superior a quatro anos. Trata-se de atribuição típica do delegado de polícia na fase do flagrante, exercida de forma fundamentada, com observância dos critérios legais, como a gravidade concreta do fato, a situação econômica do autuado e a finalidade cautelar da medida. A concessão de fiança pela autoridade policial não usurpa a competência do Poder Judiciário, uma vez que o ato está sujeito a posterior controle judicial, podendo o juiz mantê-la, modificá-la, cassá-la ou substituí-la por outras medidas cautelares. A fiança, nesse contexto, reafirma o caráter excepcional da prisão cautelar e a centralidade do princípio da necessidade, especialmente no âmbito da atuação policial.$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,104,$q$Direito Ambiental$q$,$q$A prática de crime ambiental em mar territorial — bem pertencente à União — configura, por si só, lesão a bem da União, sendo, portanto, suficiente para atrair a competência da justiça federal, independentemente da demonstração de interesse direto e específico da União.$q$,$q$A prática de crime ambiental em mar territorial — bem pertencente à União — configura, por si só, lesão a bem da União, sendo, portanto, suficiente para atrair a competência da justiça federal, independentemente da demonstração de interesse direto e específico da União.$q$,'E',1,'under_review',true,false,$q$O STJ, no julgamento do REsp 2.313.729, fixou que a simples localização do crime ambiental em mar territorial não atrai automaticamente a competência da justiça federal. A proteção ao meio ambiente é matéria de competência comum da União, estados e municípios (CF, art. 23, VI e VII), razão pela qual o mero interesse genérico e indireto da União na proteção ambiental é insuficiente para deslocar a competência. Para atrair a justiça federal, é necessária a demonstração de interesse direto e específico da União — como ocorre nos crimes praticados em unidades de conservação federal, contra espécies da lista nacional de ameaçadas, ou com caráter transnacional. A regra geral permanece sendo a competência da justiça estadual. Fundamento legal: CF, art. 109, IV e art. 23, VI e VII; STJ, ArRg no Agravo em REsp 2.313.729/SP e AgRg no Conflito de Competência 154.855/SP.$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,105,$q$Direito Ambiental$q$,$q$Considere que uma empresa de construção civil tenha sido autuada pelo órgão ambiental competente por operar em área de preservação permanente sem licença ambiental. Considere, ainda, que 20 dias após a cientificação do auto de infração, a empresa tenha optado por aderir à conversão da multa simples na modalidade indireta, por meio do custeio de projeto ambiental previamente cadastrado e selecionado pelo órgão emissor, tendo obtido desconto de 60% sobre o valor consolidado. Nessa situação, a conduta do órgão ambiental foi correta, sendo o desconto de 60% correspondente ao percentual legalmente previsto para a conversão da multa na modalidade indireta requerida juntamente com a defesa, em conformidade com a legislação vigente.$q$,$q$Considere que uma empresa de construção civil tenha sido autuada pelo órgão ambiental competente por operar em área de preservação permanente sem licença ambiental. Considere, ainda, que 20 dias após a cientificação do auto de infração, a empresa tenha optado por aderir à conversão da multa simples na modalidade indireta, por meio do custeio de projeto ambiental previamente cadastrado e selecionado pelo órgão emissor, tendo obtido desconto de 60% sobre o valor consolidado. Nessa situação, a conduta do órgão ambiental foi correta, sendo o desconto de 60% correspondente ao percentual legalmente previsto para a conversão da multa na modalidade indireta requerida juntamente com a defesa, em conformidade com a legislação vigente.$q$,'C',1,'under_review',true,false,$q$O art. 143, § 2.º, III, do Decreto n.º 6.514/2008, com redação dada pelo Decreto n.º 11.373/2023, prevê desconto de 60% sobre o valor da multa consolidada quando a conversão se der na modalidade indireta e for requerida juntamente com a defesa — percentual distinto dos 40% aplicáveis à modalidade direta no mesmo momento processual (art. 143, § 2.º, I).$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,106,$q$Direito Ambiental$q$,$q$Suponha que uma pessoa jurídica do setor sucroalcooleiro tenha sido condenada criminalmente por poluição hídrica, nos termos da Lei n.º 9.605/1998, devido ao lançamento de vinhoto em curso d’água. Suponha, ainda, que, durante a execução da pena, a empresa tenha alegado a extinção da punibilidade em razão da prescrição, com base na pena de multa que lhe fora exclusivamente aplicada e ao argumento de que, por ser ela pessoa jurídica, a prescrição deveria ser regulada por prazo próprio distinto do previsto no Código Penal. Nesse caso, a tese defensiva é correta, pois o estabelecimento de penas específicas a pessoas jurídicas pela legislação ambiental afasta a aplicação subsidiária do Código Penal no que concerne aos prazos prescricionais, devendo a prescrição ser regulada exclusivamente pelas disposições da própria lei ambiental.$q$,$q$Suponha que uma pessoa jurídica do setor sucroalcooleiro tenha sido condenada criminalmente por poluição hídrica, nos termos da Lei n.º 9.605/1998, devido ao lançamento de vinhoto em curso d’água. Suponha, ainda, que, durante a execução da pena, a empresa tenha alegado a extinção da punibilidade em razão da prescrição, com base na pena de multa que lhe fora exclusivamente aplicada e ao argumento de que, por ser ela pessoa jurídica, a prescrição deveria ser regulada por prazo próprio distinto do previsto no Código Penal. Nesse caso, a tese defensiva é correta, pois o estabelecimento de penas específicas a pessoas jurídicas pela legislação ambiental afasta a aplicação subsidiária do Código Penal no que concerne aos prazos prescricionais, devendo a prescrição ser regulada exclusivamente pelas disposições da própria lei ambiental.$q$,'E',1,'under_review',true,false,$q$O STJ (a exemplo no AgRg no REsp 1589299/SP, Rel. Ministro JOEL ILAN PACIORNIK, QUINTA TURMA, julgado em 23/05/2017, DJe de 07/06/2017 e Agravo Regimental no Agravo em Recurso Especial n. 1.621.911/SP. Relator: Ministro Rogerio Schietti Cruz, 6ª Turma, DJe de 11/09/2020) firmou entendimento de que a prescrição antes do trânsito em julgado nos crimes ambientais praticados por pessoa jurídica deve ser regulada pelos prazos previstos no art. 109 do Código Penal, aplicado subsidiariamente por força do art. 79 da Lei n.º 9.605/1998, que determina a incidência das disposições gerais do Código Penal aos crimes previstos na lei ambiental naquilo que esta for omissa. A ausência de regramento prescricional próprio na Lei n.º 9.605/1998 para pessoas jurídicas não afasta o Código Penal. Ao contrário, impõe a aplicação subsidiária.$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,107,$q$Direito Ambiental$q$,$q$A responsabilidade civil por dano ambiental tem caráter reparatório e punitivo-pedagógico, de modo que a indenização fixada aquém do valor correspondente à integralidade dos danos frustra esse duplo propósito, podendo incentivar a impunidade do degradador.$q$,$q$A responsabilidade civil por dano ambiental tem caráter reparatório e punitivo-pedagógico, de modo que a indenização fixada aquém do valor correspondente à integralidade dos danos frustra esse duplo propósito, podendo incentivar a impunidade do degradador.$q$,'C',1,'under_review',true,false,$q$O STJ reconhece que a responsabilidade civil por dano ambiental não se limita a reparar o prejuízo causado — ela também cumpre uma função punitivo-pedagógica, voltada a desestimular condutas lesivas ao meio ambiente. Por isso, fixar a indenização em valor inferior à totalidade dos danos contraria esse propósito e pode encorajar a impunidade do degradador. Esse entendimento foi firmado no AgInt no AREsp 1.890.696/RJ, Rel. min. Herman Benjamin, Segunda Turma, DJe 30/06/2022.$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,108,$q$Direito Ambiental$q$,$q$A competência fiscalizatória do IBAMA em atividades licenciadas por órgãos estaduais ou municipais somente se legitima mediante comprovação prévia de omissão ou insuficiência do órgão licenciador.$q$,$q$A competência fiscalizatória do IBAMA em atividades licenciadas por órgãos estaduais ou municipais somente se legitima mediante comprovação prévia de omissão ou insuficiência do órgão licenciador.$q$,'E',1,'under_review',true,false,$q$O STJ firmou entendimento consolidado — REsp 1.646.016/RN e Agint no AREsp 1.624.736/MS — de que a competência para licenciar não se confunde com a competência para fiscalizar, cabendo ao IBAMA o dever-poder de fiscalizar qualquer atividade que ponha em risco o meio ambiente, independentemente de qual ente seja o responsável pelo licenciamento. A exigência de comprovação prévia de omissão ou insuficiência, fixada pelo STF na ADI 4.757 ao interpretar o art. 17, § 3.º, da LC n.º 140/2011, aplica-se especificamente aos casos de duplicidade de autuações — e não como condição para a atuação federal diante de risco ambiental concreto sem autuação anterior pelo órgão licenciador.$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,109,$q$Direito Ambiental$q$,$q$As atividades e projetos que envolvam organismos geneticamente modificados (OGM) e seus derivados, relacionados ao ensino com manipulação de organismos vivos, à pesquisa científica, ao desenvolvimento tecnológico e à produção industrial são vedados a pessoas físicas em atuação autônoma e independente, salvo se mantiverem vínculo empregatício ou qualquer outro com pessoas jurídicas de direito público ou privado devidamente habilitadas.$q$,$q$As atividades e projetos que envolvam organismos geneticamente modificados (OGM) e seus derivados, relacionados ao ensino com manipulação de organismos vivos, à pesquisa científica, ao desenvolvimento tecnológico e à produção industrial são vedados a pessoas físicas em atuação autônoma e independente, salvo se mantiverem vínculo empregatício ou qualquer outro com pessoas jurídicas de direito público ou privado devidamente habilitadas.$q$,'X',1,'annulled',true,false,$q$O art. 2.º, § 2.º, da Lei n.º 11.105/2005 estabelece que tais atividades são vedadas a pessoas físicas em atuação autônoma e independente, ainda que mantenham vínculo empregatício ou qualquer outro com pessoas jurídicas — e não “salvo quando”, como afirma a assertiva. A lei expressamente afasta o vínculo institucional como causa excludente da vedação, invertendo a lógica apresentada no enunciado.$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,110,$q$Direito Ambiental$q$,$q$No SNUC, o CONAMA atua como órgão consultivo e deliberativo, com a atribuição de acompanhar a implementação do sistema, e, no SISNAMA, o CONAMA assessora, estuda e propõe ao conselho de governo diretrizes de políticas governamentais para o meio ambiente.$q$,$q$No SNUC, o CONAMA atua como órgão consultivo e deliberativo, com a atribuição de acompanhar a implementação do sistema, e, no SISNAMA, o CONAMA assessora, estuda e propõe ao conselho de governo diretrizes de políticas governamentais para o meio ambiente.$q$,'C',1,'under_review',true,false,$q$O art. 6.º, I e II, da Lei n.º 9.985/2000 posiciona o CONAMA como órgão consultivo e deliberativo do SNUC com a atribuição específica de acompanhar a implementação do sistema. Essas funções diferem das atribuídas ao CONAMA no SISNAMA pelo art. 6.º, II, da Lei n.º 6.938/1981, onde o órgão assessora, estuda e propõe ao Conselho de Governo diretrizes de políticas governamentais para o meio ambiente, além de deliberar sobre normas e padrões ambientais.$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,111,$q$Direito Ambiental$q$,$q$A reserva da biosfera pode ser estruturada em áreas-núcleo, zonas de amortecimento e em zonas de transição, estas últimas sem limites rígidos, onde o processo de ocupação e o manejo dos recursos naturais são conduzidos de modo participativo e em bases sustentáveis.$q$,$q$A reserva da biosfera pode ser estruturada em áreas-núcleo, zonas de amortecimento e em zonas de transição, estas últimas sem limites rígidos, onde o processo de ocupação e o manejo dos recursos naturais são conduzidos de modo participativo e em bases sustentáveis.$q$,'C',1,'under_review',true,false,$q$Segundo o art. 41, § 1.º, I, II e III, da Lei n.º 9.985/2000, a reserva da biosfera é constituída por: I – uma ou várias áreas núcleo, destinadas à proteção integral da natureza; II – uma ou várias zonas de amortecimento, onde só são admitidas atividades que não resultem em dano para as áreas núcleo; e III – uma ou várias zonas de transição, sem limites rígidos, onde o processo de ocupação e o manejo dos recursos naturais são planejados e conduzidos de modo participativo e em bases sustentáveis. Observa-se, portanto, que a lei atribui a expressão “sem limites rígidos” exclusivamente à zona de transição — inciso III —, sem qualquer menção equivalente às áreas-núcleo ou às zonas de amortecimento.$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,112,$q$Administração Regional e Políticas Distritais$q$,$q$A existência de múltiplos entes federativos na RIDE é um desafio para a sua articulação interna, sobretudo no que diz respeito ao alinhamento dos interesses comuns em áreas prioritárias, como infraestrutura, saneamento, educação, desenvolvimento econômico e segurança, entre outras.$q$,$q$A existência de múltiplos entes federativos na RIDE é um desafio para a sua articulação interna, sobretudo no que diz respeito ao alinhamento dos interesses comuns em áreas prioritárias, como infraestrutura, saneamento, educação, desenvolvimento econômico e segurança, entre outras.$q$,'C',1,'under_review',true,false,$q$Os interesses comuns da Região Integrada de Desenvolvimento do Distrito Federal e Entorno (RIDE) focam a articulação conjunta entre União, DF, Goiás e Minas Gerais para impulsionar o desenvolvimento regional. As áreas prioritárias incluem infraestrutura, transporte, saneamento, saúde, educação, geração de empregos e segurança pública, visando o desenvolvimento equilibrado do entorno. De acordo com o art. 3.º da Lei Complementar federal n.º 94/1998, consideram-se de interesse da RIDE os serviços públicos comuns ao Distrito Federal e aos municípios que a integram, especialmente aqueles relacionados às áreas de infraestrutura e de geração de empregos. De acordo com o parágrafo único do art. 3.º do Decreto n.º 7.469/2011, que regulamenta a LC n.º 94/1998, consideram-se de interesse da RIDE os serviços públicos comuns ao Distrito Federal, aos estados de Goiás e de Minas Gerais e aos municípios que a integram, relacionados com as seguintes áreas: I – infraestrutura; II – geração de empregos e capacitação profissional; III – saneamento básico, em especial o abastecimento de água, a coleta e o tratamento de esgoto e o serviço de limpeza pública; IV – uso, parcelamento e ocupação do solo; V – transportes e sistema viário; VI – proteção ao meio ambiente e controle da poluição ambiental; VII – aproveitamento de recursos hídricos e minerais; VIII – saúde e assistência social; IX - educação e cultura; X – produção agropecuária e abastecimento alimentar; XI – habitação popular; XII – serviços de telecomunicação; XIII – turismo; e XIV – segurança pública.$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,113,$q$Administração Regional e Políticas Distritais$q$,$q$Ao Conselho Administrativo da Região Integrada de Desenvolvimento do Distrito Federal e Entorno (COARIDE) cabe coordenar ações, políticas e planos de desenvolvimento para a RIDE.$q$,$q$Ao Conselho Administrativo da Região Integrada de Desenvolvimento do Distrito Federal e Entorno (COARIDE) cabe coordenar ações, políticas e planos de desenvolvimento para a RIDE.$q$,'C',1,'under_review',true,false,$q$Segundo o art. 2.º do Decreto n. 7.469/2011, com redação dada pelo Decreto n.º 11.911, de 2024, o COARIDE é vinculado ao Ministério da Integração e do Desenvolvimento Regional, e não ao Ministério do Desenvolvimento, Indústria, Comércio e Serviços, e sua finalidade é coordenar as atividades a serem desenvolvidas na RIDE.$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,114,$q$Administração Regional e Políticas Distritais$q$,$q$Isenções e incentivos fiscais em caráter definitivo, isenções e descontos em tarifas, fretes e seguro, bem como linhas de crédito subsidiados são algumas das ações de desenvolvimento regional e atração de investimentos e empresas para os municípios goianos e mineiros que integram a RIDE, com o objetivo de gerar desenvolvimento regional e diminuição das desigualdades locais.$q$,$q$Isenções e incentivos fiscais em caráter definitivo, isenções e descontos em tarifas, fretes e seguro, bem como linhas de crédito subsidiados são algumas das ações de desenvolvimento regional e atração de investimentos e empresas para os municípios goianos e mineiros que integram a RIDE, com o objetivo de gerar desenvolvimento regional e diminuição das desigualdades locais.$q$,'E',1,'under_review',true,false,$q$De acordo com o art. 8.º do Decreto federal n.º 7.469/2011, o “Programa Especial de Desenvolvimento do Entorno do Distrito Federal, ouvidos os órgãos competentes, estabelecerá, mediante convênio, normas e critérios para a unificação de procedimentos relativos aos serviços públicos de responsabilidade Distrital, Estadual e Municipal de entes que integram a RIDE, especialmente em relação a: I – tarifas, fretes e seguro, ouvido o Ministério da Fazenda; II – linhas de crédito especiais para atividades prioritárias; III – isenções e incentivos fiscais, em caráter temporário, de fomento a atividades produtivas em programas de geração de empregos e de fixação de mão de obra.$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,115,$q$Administração Regional e Políticas Distritais$q$,$q$Conforme a legislação pertinente, programas e projetos prioritários para a RIDE, principalmente os de infraestrutura básica e geração de empregos, serão financiados com recursos do orçamento da União, dos orçamentos do Distrito Federal, dos estados de Goiás e Minas Gerais, bem como dos municípios integrantes da RIDE, e de operações de crédito externas e internas.$q$,$q$Conforme a legislação pertinente, programas e projetos prioritários para a RIDE, principalmente os de infraestrutura básica e geração de empregos, serão financiados com recursos do orçamento da União, dos orçamentos do Distrito Federal, dos estados de Goiás e Minas Gerais, bem como dos municípios integrantes da RIDE, e de operações de crédito externas e internas.$q$,'C',1,'under_review',true,false,$q$A assertiva está de acordo com o previsto no art. 9.º do Decreto federal n.º 7.469/2011: “Art. 9.º Os programas e projetos prioritários para a RIDE, principalmente no que se refere à infraestrutura básica e geração de empregos, serão financiados com recursos: I – do orçamento da União; II – dos orçamentos do Distrito Federal, dos Estados de Goiás e de Minas Gerais e dos Municípios abrangidos pela RIDE; e III – de operações de crédito externas e internas.”$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,116,$q$Administração Regional e Políticas Distritais$q$,$q$O Comitê de Articulação e Monitoramento do II PDPM é competente para efetuar ajustes nos objetivos e metas do plano, por meio de deliberação, mediante resolução, por maioria simples dos presentes, cabendo à coordenadora o voto de qualidade em caso de empate.$q$,$q$O Comitê de Articulação e Monitoramento do II PDPM é competente para efetuar ajustes nos objetivos e metas do plano, por meio de deliberação, mediante resolução, por maioria simples dos presentes, cabendo à coordenadora o voto de qualidade em caso de empate.$q$,'C',1,'under_review',true,false,$q$O art. 8.º do Decreto distrital n.º 42.590/2021 prevê deliberação mediante resolução por maioria simples dos presentes, com voto de qualidade da coordenadora em caso de empate. O artigo 5.º enumera as competências do Comitê de Articulação e Monitoramento do II PDPM, prevendo, no inciso V, a competência de “efetuar ajustes de objetivos, ações e metas do II PDPM”.$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,117,$q$Administração Regional e Políticas Distritais$q$,$q$São objetivos específicos do Comitê de Articulação e Monitoramento do II PDPM: articular, monitorar e avaliar periodicamente o cumprimento das metas definidas no II PDPM.$q$,$q$São objetivos específicos do Comitê de Articulação e Monitoramento do II PDPM: articular, monitorar e avaliar periodicamente o cumprimento das metas definidas no II PDPM.$q$,'E',1,'under_review',true,false,$q$As ações expressas no item compõem o objetivo geral do Comitê de articulação e Monitoramento do II PDPM, de acordo com o Decreto distrital n.º 42.590/2021: “Art. 6º O Comitê de Articulação e Monitoramento do II PDPM tem como Objetivo Geral: I - articular, monitorar e avaliar periodicamente o cumprimento dos objetivos, metas e ações definidos no II PDPM. Os objetivos específicos estão dispostos no artigo 7.º do Decreto n.º 42.590/2021.$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,118,$q$Administração Regional e Políticas Distritais$q$,$q$Entre os objetivos específicos do eixo que, no II PDPM, trata da igualdade para mulheres jovens, mulheres idosas e mulheres com deficiência, é prevista a garantia da igualdade de direitos e oportunidades no acesso, na permanência e na promoção das jovens, das idosas e das mulheres com deficiência no mercado de trabalho.$q$,$q$Entre os objetivos específicos do eixo que, no II PDPM, trata da igualdade para mulheres jovens, mulheres idosas e mulheres com deficiência, é prevista a garantia da igualdade de direitos e oportunidades no acesso, na permanência e na promoção das jovens, das idosas e das mulheres com deficiência no mercado de trabalho.$q$,'C',1,'under_review',true,false,$q$O item está de acordo com o segundo objetivo específico do eixo 9 do II PDPM: EIXO 9 IGUALDADE PARA AS MULHERES JOVENS, MULHERES IDOSAS E MULHERES COM DEFICIÊNCIA (...) Objetivos Específicos (...) - Garantir a igualdade de direitos e oportunidades no acesso, na permanência e na promoção das jovens, das idosas e das mulheres com deficiência no mercado de trabalho; (...)$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,119,$q$Primeiros Socorros$q$,$q$O serviço de emergência deve ser acionado imediatamente.$q$,$q$O serviço de emergência deve ser acionado imediatamente.$q$,'C',1,'under_review',true,false,$q$A ativação precoce do sistema de emergência é um dos primeiros elos da cadeia de sobrevivência, conforme as Diretrizes de 2025 da American Heart Association para Suporte Básico de Vida em Adultos.$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$),
(2026,120,$q$Primeiros Socorros$q$,$q$A vítima deve ser colocada em posição lateral de segurança o mais rapidamente possível.$q$,$q$A vítima deve ser colocada em posição lateral de segurança o mais rapidamente possível.$q$,'E',1,'under_review',true,false,$q$A providência descrita no item só é indicada se houver respiração normal, conforme a literatura de referência na área de primeiros socorros.$q$,$q$Transcrição verbatim do caderno de provas (PROVA OBJETIVA P1, CEBRASPE - PCDF Delegado 2026); gabarito conferido no GABARITO DEFINITIVO - PROVA OBJETIVA (P1), Matriz 184_PC_DF_EDELEGADO_001_00. Base legal ainda não conferida individualmente no planalto.gov.br/fonte oficial de cada norma citada — aguardando revisão item a item antes de content_status=active.$q$)
), editions as (
  select id,contest_year from public.syllabus_editions
  where contest_name='Polícia Civil do Distrito Federal' and role_name='Delegado de Polícia' and contest_year=2026
), resolved as (
  select imported.*, question_source.id question_source_id, answer_source.id answer_key_source_id, topic.id syllabus_topic_id
  from imported
  join editions on editions.contest_year=imported.exam_year
  join public.syllabus_topics topic on topic.edition_id=editions.id and topic.discipline=imported.subject and topic.topic_order=1
  join public.content_sources question_source on question_source.title='Prova objetiva PCDF - Delegado - ' || imported.exam_year
  join public.content_sources answer_source on answer_source.title='Gabarito definitivo PCDF - Delegado - ' || imported.exam_year
)
insert into public.official_exam_questions (
  question_source_id,answer_key_source_id,syllabus_topic_id,contest_name,career_name,exam_board,exam_year,item_number,subject,
  question_text,raw_extraction,official_answer,source_page,content_status,legal_review_required,
  context_review_required,review_note,legal_basis
)
select question_source_id,answer_key_source_id,syllabus_topic_id,'Polícia Civil do Distrito Federal','Delegado de Polícia','CEBRASPE',exam_year,item_number,subject,
  question_text,raw_extraction,official_answer,source_page,content_status,legal_review_required,
  context_review_required,review_note,
  jsonb_build_array(jsonb_build_object('justificativa',legal_basis_text,'fonte','Gabarito preliminar com justificativas - CEBRASPE PCDF Delegado 2026'))
from resolved
on conflict (contest_name,career_name,exam_year,item_number) do nothing;
